export const SOURCES: Record<string, string> = {
  "server.ts": "/**\n * Copilot Runtime for this harness.\n *\n * Shape comes from the Angular quickstart's Node runtime server, with the\n * agent swapped for the Microsoft Agent Framework (.NET) backend in\n * `../backend`.\n *\n * That backend exposes plain AG-UI endpoints — `app.MapAGUI(...)` in\n * backend/Program.cs mounts `POST /` (the default agent), `POST /subagents`\n * (the Sub-Agents supervisor) and `POST /research` (the AG-UI guide's\n * `research-agent`), each streaming AG-UI events over SSE.\n *\n * `default` and `support` resolve to the same Agent Framework agent.\n * `support` exists so the doc snippets that use `agentId=\"support\"` (Chat UI,\n * Threads) run verbatim. The agents-map key is the only name the frontend can\n * ask for (Copilot Runtime guide, \"Which name identifies an agent\").\n *\n * `a2ui: {}` enables A2UIMiddleware for every registered agent, per\n * https://docs.copilotkit.ai/angular/ms-agent-harness-dotnet/backend/copilot-runtime\n * — it is a runtime-side middleware and is independent of which agent binding\n * is used.\n *\n * Ports: backend/Program.cs binds 8251, so the runtime takes 8250. Override\n * either side with PORT / MICROSOFT_AGENT_FRAMEWORK_URL.\n */\n// quickstart : copilot runtime\nimport { createServer } from \"node:http\";\nimport { CopilotRuntime, CopilotKitIntelligence } from \"@copilotkit/runtime/v2\";\nimport { createCopilotNodeListener } from \"@copilotkit/runtime/v2/node\";\nimport { HttpAgent } from \"@ag-ui/client\";\n\nconst agentUrl =\n  process.env[\"MICROSOFT_AGENT_FRAMEWORK_URL\"] ?? \"http://localhost:8251/\";\n\n/**\n * Intelligence client, verbatim from\n * https://docs.copilotkit.ai/angular/ms-agent-harness-dotnet/intelligence/connect-your-runtime\n * (\"Wire the runtime\"). Thread endpoints are served by Intelligence, so the\n * Threads guide's `injectThreads` list and `CopilotThreadsDrawer` resolve to\n * nothing until this is passed — which that guide never says.\n *\n * `apiUrl`/`wsUrl` default to the managed platform, so both stay unset.\n */\nconst intelligence = new CopilotKitIntelligence({\n  apiKey: process.env[\"CPK_INTELLIGENCE_API_KEY\"]!,\n});\n\n// quickstart : copilot runtime start\nconst runtime = new CopilotRuntime({\n  agents: {\n    // quickstart : connect selected agent backend\n    default: new HttpAgent({ url: agentUrl }),\n    // chat ui : support agent\n    support: new HttpAgent({ url: agentUrl }),\n    // subagents : supervisor agent (backend/SubagentsAgent.cs)\n    subagents: new HttpAgent({ url: `${agentUrl}subagents` }),\n    // ag-ui : research agent (backend/ResearchAgent.cs, self-defined)\n    \"research-agent\": new HttpAgent({ url: `${agentUrl}research` }),\n  },\n  // a2ui : enable a2ui middleware start\n  a2ui: {},\n  // a2ui : enable a2ui middleware end\n  intelligence,\n  // Threads are per-user. Without this every visitor shares one history.\n  identifyUser: (request) => ({\n    id: request.headers.get(\"x-user-id\") ?? \"anonymous\",\n    name: request.headers.get(\"x-user-name\") ?? \"Anonymous\",\n  }),\n});\n// quickstart : copilot runtime end\n\nconst port = Number(process.env[\"PORT\"] ?? 8250);\n\n/**\n * The app is served from another origin than the runtime: `ng serve`\n * (package.json `start`) and the built SSR server (src/server.ts). Both are\n * listed, with the headers the client sends (`content-type`, the license\n * header `provideCopilotKit` adds when a key is set, and the `x-user-*`\n * headers `identifyUser` reads).\n *\n * The ms-agent-dotnet harness also enables credentials here, for its\n * Authentication guide; that guide is not part of this harness.\n */\nconst cors = {\n  origin: [\"http://localhost:4250\", \"http://localhost:4252\"],\n  allowHeaders: [\n    \"content-type\",\n    \"x-copilotcloud-public-api-key\",\n    \"x-user-id\",\n    \"x-user-name\",\n  ],\n};\n\n\n// quickstart : create copilot node listener start\nconst listener = createCopilotNodeListener({\n  runtime,\n  basePath: \"/api/copilotkit\",\n  cors,\n});\n\ncreateServer(listener).listen(port, () => {\n  console.log(\n    `Copilot Runtime listening at http://localhost:${port}/api/copilotkit`,\n  );\n  console.log(`Microsoft Agent Framework (.NET) agent: ${agentUrl}`);\n});\n// quickstart : create copilot node listener end\n",
  "src/styles.css": "@import 'tailwindcss';\n\n/* Quickstart step \"Import the styles\". Self-contained — the chat renders\n   without any other CSS.\n   https://docs.copilotkit.ai/angular/ms-agent-harness-dotnet/quickstart */\n\n/* quickstart : import the styles start */\n@import '@copilotkit/angular/styles.css';\n\n/* ------------------------------------------------------------------ */\n/* Harness chrome tokens                                              */\n/* `--line` and `--muted` are referenced by the A2UI guide's CSS below, */\n/* which does not define them itself.                                  */\n/* ------------------------------------------------------------------ */\n:root {\n  /* Surfaces */\n  --bg: #f4f6fa;\n  --surface: #ffffff;\n  --surface-sunken: #eef1f7;\n\n  /* Text — all AA or better on --surface */\n  --ink: #0d1526;\n  --ink-soft: #33415a;\n  --muted: #5c6a86;\n\n  /* Lines */\n  --line: #e0e5ee;\n  --line-strong: #c6cedd;\n\n  /* Accent */\n  --accent: #4f46e5;\n  --accent-hover: #4338ca;\n  --accent-soft: #eef0ff;\n  --accent-ink: #362fa8;\n\n  /* Code surface */\n  --code-bg: #0b1220;\n  --code-bar: #131c2f;\n  --code-ink: #dbe3f0;\n  --code-line: #24304a;\n}\n\nhtml,\nbody {\n  height: 100%;\n  margin: 0;\n  color: var(--ink);\n  background: var(--bg);\n  font-family:\n    'Inter',\n    -apple-system,\n    BlinkMacSystemFont,\n    'Segoe UI',\n    Roboto,\n    Helvetica,\n    Arial,\n    sans-serif;\n  -webkit-font-smoothing: antialiased;\n}\n\n/* Visible keyboard focus everywhere in the harness chrome (WCAG 2.4.7). */\na:focus-visible,\nbutton:focus-visible,\n[tabindex]:focus-visible {\n  outline: 2px solid var(--accent);\n  outline-offset: 2px;\n  border-radius: 0.375rem;\n}\n\n/* Inline code in prose — distinct from the dark code blocks. */\n.prose-inline-code,\np > code,\nli > code,\ntd > code {\n  padding: 0.1rem 0.35rem;\n  border: 1px solid var(--line);\n  border-radius: 0.3rem;\n  background: var(--surface-sunken);\n  color: var(--accent-ink);\n  font-size: 0.85em;\n}\n\n/* ------------------------------------------------------------------ */\n/* Code figures                                                        */\n/* ------------------------------------------------------------------ */\n.code-figure {\n  overflow: hidden;\n  border: 1px solid var(--code-line);\n  border-radius: 0.75rem;\n  background: var(--code-bg);\n  box-shadow: 0 12px 28px -22px rgb(11 18 32 / 0.65);\n}\n\n/* Quoted-from-docs samples read as secondary to the code that runs. */\n.code-figure--quoted {\n  border-style: dashed;\n  border-color: var(--line-strong);\n}\n\n.code-figure__bar {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 0.5rem 1rem;\n  align-items: center;\n  justify-content: space-between;\n  padding: 0.5rem 0.85rem;\n  border-bottom: 1px solid var(--code-line);\n  background: var(--code-bar);\n}\n\n.code-figure__path-group {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 0.45rem;\n  min-width: 0;\n}\n\n.code-figure__path {\n  color: #b9c6de;\n  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;\n  font-size: 0.72rem;\n  word-break: break-all;\n}\n\n.code-figure__copy-path,\n.code-figure__open-ide {\n  display: inline-flex;\n  align-items: center;\n  gap: 0.3rem;\n  padding: 0.12rem 0.45rem;\n  border: 1px solid #2f3d5c;\n  border-radius: 0.35rem;\n  background: #141f33;\n  color: #a5b4cd;\n  font-size: 0.68rem;\n  font-weight: 500;\n  cursor: pointer;\n  text-decoration: none;\n  transition: all 0.15s ease;\n  line-height: 1.2;\n}\n\n.code-figure__copy-path:hover,\n.code-figure__open-ide:hover {\n  background: #22304d;\n  border-color: #3e517a;\n  color: #f1f5f9;\n}\n\n.code-figure__icon {\n  width: 0.85rem;\n  height: 0.85rem;\n  flex-shrink: 0;\n}\n\n.code-figure__meta {\n  display: flex;\n  flex-shrink: 0;\n  gap: 0.5rem;\n  align-items: center;\n}\n\n.code-figure__note {\n  color: #93a3c0;\n  font-size: 0.72rem;\n}\n\n.code-figure__lang,\n.code-figure__badge {\n  padding: 0.1rem 0.45rem;\n  border-radius: 999px;\n  background: #22304d;\n  color: #a9b8d6;\n  font-size: 0.65rem;\n  font-weight: 600;\n  letter-spacing: 0.02em;\n  text-transform: uppercase;\n}\n\n.code-figure__badge {\n  background: #3b2f18;\n  color: #e6c07b;\n}\n\n.code-figure__copy {\n  padding: 0.15rem 0.55rem;\n  border: 1px solid #2f3d5c;\n  border-radius: 0.35rem;\n  background: transparent;\n  color: #b9c6de;\n  font-size: 0.7rem;\n  font-weight: 600;\n  cursor: pointer;\n  transition: background 0.15s ease;\n}\n\n.code-figure__copy:hover {\n  background: #22304d;\n  color: #e6edf9;\n}\n\n.code-figure__pre {\n  max-height: 32rem;\n  margin: 0;\n  overflow: auto;\n  padding: 1rem;\n  color: var(--code-ink);\n  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;\n  font-size: 0.78rem;\n  line-height: 1.65;\n  tab-size: 2;\n}\n\n/* ------------------------------------------------------------------ */\n/* highlight.js theme — tuned for contrast on --code-bg                */\n/* ------------------------------------------------------------------ */\n.hljs-comment,\n.hljs-quote {\n  color: #8494b3;\n  font-style: italic;\n}\n\n.hljs-keyword,\n.hljs-selector-tag,\n.hljs-literal,\n.hljs-doctag {\n  color: #c4b5fd;\n}\n\n.hljs-string,\n.hljs-regexp,\n.hljs-addition {\n  color: #8ee7a5;\n}\n\n.hljs-number,\n.hljs-symbol,\n.hljs-bullet {\n  color: #fcd34d;\n}\n\n.hljs-title,\n.hljs-title.function_,\n.hljs-section {\n  color: #7dd3fc;\n}\n\n.hljs-title.class_,\n.hljs-type,\n.hljs-built_in,\n.hljs-class .hljs-title {\n  color: #fdba74;\n}\n\n.hljs-attr,\n.hljs-attribute,\n.hljs-property,\n.hljs-variable,\n.hljs-template-variable {\n  color: #f0abfc;\n}\n\n.hljs-name,\n.hljs-selector-id,\n.hljs-selector-class,\n.hljs-tag {\n  color: #fb7185;\n}\n\n.hljs-meta,\n.hljs-params,\n.hljs-punctuation {\n  color: #a5b4cd;\n}\n\n.hljs-deletion {\n  color: #fca5a5;\n}\n\n.hljs-emphasis {\n  font-style: italic;\n}\n\n.hljs-strong {\n  font-weight: 700;\n}\n\n/* chat ui : scope css changes start */\n.support-chat .copilotKitUserMessage {\n  color: white;\n  background: #2563eb;\n  border-radius: 0.75rem;\n}\n\n.support-chat .copilotKitAssistantMessage {\n  padding: 0.75rem;\n  color: #172554;\n  background: #eff6ff;\n  border-radius: 0.75rem;\n}\n/* chat ui : scope css changes end */\n\n/* a2ui : style rendered components start */\n.a2ui-row {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: stretch;\n  width: 100%;\n}\n\n.a2ui-row > * {\n  flex: 1 1 10rem;\n  min-width: 0;\n}\n\n.a2ui-column {\n  display: flex;\n  flex-direction: column;\n  width: 100%;\n}\n\n[data-testid='declarative-card'],\n.a2ui-chart-card,\n.a2ui-flight-card {\n  display: block;\n  padding: 1rem;\n  border: 1px solid var(--line);\n  border-radius: 0.9rem;\n  background: white;\n  box-shadow: 0 8px 22px -18px rgb(15 23 42 / 0.4);\n}\n\n.a2ui-metric {\n  display: grid;\n  min-width: 8rem;\n  gap: 0.25rem;\n}\n\n.a2ui-metric > span,\n.a2ui-metric > small {\n  color: var(--muted);\n  font-size: 0.75rem;\n}\n\n.a2ui-metric > strong {\n  font-size: 1.4rem;\n}\n\n.a2ui-status,\n.a2ui-airline {\n  display: inline-flex;\n  width: fit-content;\n  padding: 0.25rem 0.55rem;\n  border-radius: 999px;\n  background: #eef2ff;\n  font-size: 0.75rem;\n  font-weight: 700;\n}\n\n.a2ui-status-success {\n  background: #dcfce7;\n  color: #166534;\n}\n.a2ui-status-warning {\n  background: #fef3c7;\n  color: #92400e;\n}\n.a2ui-status-error {\n  background: #fee2e2;\n  color: #991b1b;\n}\n/* a2ui : style rendered components end */\n",
  "src/app/app.config.ts": "import {\n  ApplicationConfig,\n  provideBrowserGlobalErrorListeners,\n} from '@angular/core';\nimport { provideRouter, withInMemoryScrolling } from '@angular/router';\nimport { provideClientHydration } from '@angular/platform-browser';\nimport {\n  provideCopilotKit,\n  type SandboxFunction,\n} from '@copilotkit/angular';\nimport { z } from 'zod';\n\nimport { routes } from './app.routes';\nimport { catalog } from './features/a2ui/a2ui-catalog';\n\n// frontend tools : open generative ui host function start\nconst setDashboardFilter: SandboxFunction<{ filter: string }> = {\n  name: 'setDashboardFilter',\n  description: 'Set the active dashboard filter',\n  parameters: z.object({ filter: z.string() }),\n  handler: async ({ filter }) => {\n    sessionStorage.setItem('dashboard-filter', filter);\n    return { applied: filter };\n  },\n};\n// frontend tools : open generative ui host function end\n\n\n/**\n * One provider at the application root, so a conversation started on any demo\n * route continues on every other route.\n *\n * `runtimeUrl` points at the Copilot Runtime from the quickstart — the\n * supported path, where the browser never talks to the Microsoft Agent\n * Framework agent directly. The `HttpAgent` binding that reaches the Agent\n * Framework AG-UI endpoint lives server-side in frontend/server.ts.\n *\n * `a2ui.catalog` / `a2ui.recovery` and `openGenerativeUI.sandboxFunctions` are\n * the A2UI and generative-UI guide options. The catalog is the A2UI guide's\n * \"Use existing web components\" one; supplying a catalog is what registers the\n * render_a2ui renderer.\n */\nexport const appConfig: ApplicationConfig = {\n  providers: [\n    provideBrowserGlobalErrorListeners(),\n    provideRouter(\n      routes,\n      withInMemoryScrolling({ scrollPositionRestoration: 'top' }),\n    ),\n    provideClientHydration(),\n    // quickstart : connect to copilot runtime start\n    provideCopilotKit({\n      runtimeUrl: 'http://localhost:8250/api/copilotkit',\n      // a2ui : recover incomplete streams start\n      a2ui: {\n        // The guide's app.config sample passes `catalog: productCatalog`,\n        // which it never defines. The one catalog it does build is the\n        // \"Use existing web components\" one (features/a2ui/a2ui-catalog.ts),\n        // so that is the catalog passed here.\n        catalog,\n        recovery: { showAfterMs: 2_000, showAfterAttempts: 2 },\n      },\n      // a2ui : recover incomplete streams end\n      // frontend tools : open generative ui start\n      openGenerativeUI: {\n        // `sandboxFunctions` is typed `SandboxFunction[]`, i.e.\n        // `SandboxFunction<Record<string, unknown>>[]`, so the guide's\n        // `SandboxFunction<{ filter: string }>` is not assignable to it as\n        // written. Cast at the array site, the same idiom the docs use for the\n        // equivalent `component` variance problem. See README known issues.\n        sandboxFunctions: [setDashboardFilter as unknown as SandboxFunction],\n      },\n      // frontend tools : open generative ui end\n    }),\n    // quickstart : connect to copilot runtime end\n  ],\n};\n",
  "src/app/features/a2ui/a2ui-catalog.ts": "/**\n * \"Use existing web components\", from\n * https://docs.copilotkit.ai/angular/ms-agent-harness-dotnet/guides/a2ui#use-existing-web-components\n * (published as src/app/a2ui-catalog.ts).\n *\n * The `createAngularCatalog(...)` call between the region markers is the\n * guide's, unchanged. The guide shows it as a fragment, so two things are\n * added around it, and nothing inside it:\n * - the imports it uses (`z`, `createAngularCatalog`, `ChildListSchema`,\n *   `AcmeBadge`, `PanelComponent`);\n * - `export { catalog }`, so app.config.ts can pass it to `provideCopilotKit`\n *   as the guide's \"Give each catalog a stable catalogId, then select it in\n *   the a2ui option\" section says to.\n *\n * `AcmeBadge` and `PanelComponent` are not defined by the guide; see their\n * files.\n */\nimport { z } from \"zod\";\nimport { ChildListSchema, createAngularCatalog } from \"@copilotkit/angular/a2ui\";\n\nimport { AcmeBadge } from \"./acme-badge.element\";\nimport { PanelComponent } from \"./panel.component\";\n\n// a2ui : use existing web components start\nconst catalog = createAngularCatalog(\n  {\n    Badge: { props: z.object({ label: z.string() }) },\n    Panel: { props: z.object({ children: ChildListSchema }) },\n  },\n  {\n    Badge: { tagName: \"acme-badge\", element: AcmeBadge },\n    Panel: PanelComponent,\n  },\n  { includeBasicCatalog: true },\n);\n// a2ui : use existing web components end\n\nexport { catalog };\n",
  "src/app/features/a2ui/a2ui-chat.component.ts": "// a2ui : a2ui chat start\n/**\n * A2UI needs no component-level wiring: the runtime applies A2UIMiddleware\n * (`a2ui: {}` in frontend/server.ts) and, per the guide, \"on the frontend, the\n * A2UI renderer activates automatically. No extra configuration is needed.\"\n *\n * The recovery thresholds the guide prescribes are set once in\n * src/app/app.config.ts, and its catalog CSS lives in src/styles.css.\n * https://docs.copilotkit.ai/angular/ms-agent-harness-dotnet/guides/a2ui\n */\n\nimport { Component } from '@angular/core';\nimport { CopilotChat } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-a2ui-chat',\n  imports: [CopilotChat],\n  template: `\n    <div style=\"height: 100%\">\n      <copilot-chat />\n    </div>\n  `,\n})\nexport class A2uiChatComponent {}\n// a2ui : a2ui chat end\n",
  "src/app/features/a2ui/a2ui-element.ts": "/**\n * Copied unchanged (apart from this header) from the CopilotKit Angular demo,\n * examples/v2/angular/demo/src/app/routes/a2ui-web-components/a2ui-element.ts.\n *\n * The A2UI guide says a custom element \"reads its props and writes to the\n * data model through that context, for example with web_core's\n * `GenericBinder`\", but shows no element. This is the demo's base class that\n * does exactly that; AcmeBadge extends it. `@a2ui/web_core` is a dependency of\n * `@copilotkit/angular` and is not declared in this repo's package.json.\n */\nimport type { ComponentContext } from \"@a2ui/web_core/v0_9\";\nimport { GenericBinder } from \"@a2ui/web_core/v0_9\";\nimport type { A2uiWebComponentElement } from \"@copilotkit/angular/a2ui\";\nimport type { ZodTypeAny } from \"zod\";\n\n/**\n * A plain Custom Element base for A2UI catalog entries. The renderer assigns\n * `context`; the element binds its schema to it with web_core's\n * `GenericBinder` and re-renders whenever the resolved props change. Dynamic\n * props come with `set*` setters that write back to the data model.\n */\nexport abstract class A2uiElement<Props>\n  extends HTMLElement\n  implements A2uiWebComponentElement\n{\n  protected abstract readonly schema: ZodTypeAny;\n  protected abstract render(props: Props): void;\n\n  #context?: ComponentContext;\n  #binder?: GenericBinder<Props>;\n  #subscription?: { unsubscribe(): void };\n\n  constructor() {\n    super();\n    this.attachShadow({ mode: \"open\" });\n  }\n\n  get context(): ComponentContext | undefined {\n    return this.#context;\n  }\n\n  set context(context: ComponentContext | undefined) {\n    this.#context = context;\n    this.#bind();\n  }\n\n  // Angular may move the element (for example when siblings reorder), which\n  // disconnects and reconnects it; bind only while it is in the document.\n  connectedCallback(): void {\n    this.#bind();\n  }\n\n  disconnectedCallback(): void {\n    this.#unbind();\n  }\n\n  #bind(): void {\n    this.#unbind();\n    if (!this.#context || !this.isConnected) return;\n    this.#binder = new GenericBinder<Props>(this.#context, this.schema);\n    this.#subscription = this.#binder.subscribe((props) => this.render(props));\n    this.render(this.#binder.snapshot);\n  }\n\n  #unbind(): void {\n    this.#subscription?.unsubscribe();\n    this.#subscription = undefined;\n    this.#binder?.dispose();\n    this.#binder = undefined;\n  }\n}\n",
  "src/app/features/a2ui/acme-badge.element.ts": "/**\n * SELF-DEFINED — `AcmeBadge`, the custom element the A2UI guide's\n * \"Use existing web components\" catalog registers as `acme-badge` but never\n * shows (it stands for \"a component from an existing design system\").\n *\n * No CopilotKit source defines it. It follows the pattern of the Angular\n * demo's web-component elements (examples/v2/angular/demo/src/app/routes/\n * a2ui-web-components/elements.ts): extend `A2uiElement`, bind the entry's\n * props schema — the guide's `z.object({ label: z.string() })` — and render\n * into the shadow root.\n */\nimport { z } from \"zod\";\n\nimport { A2uiElement } from \"./a2ui-element\";\n\ninterface BadgeProps {\n  label: string;\n}\n\nexport class AcmeBadge extends A2uiElement<BadgeProps> {\n  protected readonly schema = z.object({ label: z.string() });\n\n  protected render(props: BadgeProps): void {\n    const root = this.shadowRoot!;\n    root.innerHTML = `\n      <style>\n        :host { display: inline-block; margin: 4px; }\n        span { display: inline-block; padding: 2px 8px; border-radius: 999px;\n          background: #1e3a8a; color: #fff; font: 600 12px/1.6 system-ui, sans-serif; }\n      </style>\n      <span></span>\n    `;\n    // The label comes from the agent, so it is set as text, never as HTML.\n    root.querySelector(\"span\")!.textContent = props.label ?? \"\";\n  }\n}\n",
  "src/app/features/a2ui/panel.component.ts": "/**\n * `PanelComponent`, which the A2UI guide's \"Use existing web components\"\n * catalog registers but never shows.\n *\n * From the CopilotKit Angular demo,\n * examples/v2/angular/demo/src/app/routes/a2ui-web-components/catalog.ts,\n * cut down to the guide's definition: the guide's Panel has only\n * `children: ChildListSchema`, so the demo's `title` / `tone` header is left\n * out. Children render through the package's `copilot-a2ui-child`, which\n * renders Angular components and web components alike.\n */\nimport { Component, input } from \"@angular/core\";\nimport { z } from \"zod\";\nimport type { A2UICatalogDefinitions, A2UIProps } from \"@copilotkit/angular/a2ui\";\nimport { ChildListSchema, CopilotA2UIChild } from \"@copilotkit/angular/a2ui\";\n\n/** The guide's Panel definition, repeated here to type the component's props. */\nconst panelDefinitions = {\n  Panel: { props: z.object({ children: ChildListSchema }) },\n} satisfies A2UICatalogDefinitions;\n\n@Component({\n  selector: \"app-a2ui-panel\",\n  imports: [CopilotA2UIChild],\n  host: { style: \"display: contents\" },\n  template: `\n    <section class=\"panel\">\n      @for (child of props().children; track $index) {\n        <copilot-a2ui-child [child]=\"child\" />\n      }\n    </section>\n  `,\n  styles: `\n    .panel {\n      display: flex;\n      flex-direction: column;\n      gap: 8px;\n      margin: 8px;\n      padding: 12px 14px;\n      border: 1px solid #2563eb;\n      border-radius: 12px;\n      background: color-mix(in srgb, #2563eb 6%, white);\n    }\n  `,\n})\nexport class PanelComponent {\n  readonly props = input.required<A2UIProps<typeof panelDefinitions, \"Panel\">>();\n}\n",
  "src/app/features/ag-ui/ag-ui-chat.component.ts": "/**\n * Mounts the AG-UI guide's two `research-agent` snippets beside a chat bound\n * to the same agent, so a run has something to count and log.\n * https://docs.copilotkit.ai/angular/ms-agent-harness-dotnet/ag-ui\n */\nimport { Component } from '@angular/core';\nimport { CopilotChat } from '@copilotkit/angular';\n\nimport { AgentEventsComponent } from './agent-events.component';\nimport { AgentStatusComponent } from './agent-status.component';\n\n@Component({\n  selector: 'app-ag-ui-chat',\n  imports: [CopilotChat, AgentStatusComponent, AgentEventsComponent],\n  template: `\n    <div style=\"display: flex; height: 100%; gap: 1rem\">\n      <div style=\"width: 20rem; overflow-y: auto; padding: 1rem\">\n        <app-agent-status />\n        <app-agent-events />\n      </div>\n      <div style=\"flex: 1; min-width: 0\">\n        <copilot-chat agentId=\"research-agent\" />\n      </div>\n    </div>\n  `,\n})\nexport class AgUiChatComponent {}\n",
  "src/app/features/ag-ui/agent-events.component.ts": "// ag-ui : subscribing to ag-ui events start\n/**\n * \"Subscribing to AG-UI events\", verbatim.\n * https://docs.copilotkit.ai/angular/ms-agent-harness-dotnet/ag-ui\n *\n * The guide gives only the class members; the decorator and imports around\n * them are the minimum needed to mount it. Output goes to the browser console.\n */\nimport { Component, DestroyRef, inject } from \"@angular/core\";\nimport { injectAgentStore } from \"@copilotkit/angular\";\n\n@Component({\n  selector: \"app-agent-events\",\n  template: ``,\n})\nexport class AgentEventsComponent {\n  private readonly destroyRef = inject(DestroyRef);\n  readonly store = injectAgentStore(\"research-agent\");\n\n  constructor() {\n    const subscription = this.store().agent.subscribe({\n      onTextMessageContentEvent({ textMessageBuffer }) {\n        console.log(\"Streaming text:\", textMessageBuffer);\n      },\n      onToolCallEndEvent({ toolCallName, toolCallArgs }) {\n        console.log(\"Tool called:\", toolCallName, toolCallArgs);\n      },\n      onStateChanged({ agent }) {\n        console.log(\"State changed:\", agent.state);\n      },\n    });\n    this.destroyRef.onDestroy(() => subscription.unsubscribe());\n  }\n}\n// ag-ui : subscribing to ag-ui events end\n",
  "src/app/features/ag-ui/agent-status.component.ts": "// ag-ui : agent status component start\n/**\n * \"Accessing your agent with injectAgentStore\", verbatim.\n * https://docs.copilotkit.ai/angular/ms-agent-harness-dotnet/ag-ui\n *\n * `research-agent` is registered in server.ts and backed by\n * backend/ResearchAgent.cs, so the guide's id resolves.\n */\nimport { Component, computed } from \"@angular/core\";\nimport { injectAgentStore } from \"@copilotkit/angular\";\n\n@Component({\n  selector: \"app-agent-status\",\n  template: `\n    <p>{{ messageCount() }} messages</p>\n    @if (store().isRunning()) {\n      <p>Agent is running…</p>\n    }\n  `,\n})\nexport class AgentStatusComponent {\n  readonly store = injectAgentStore(\"research-agent\");\n  readonly messageCount = computed(() => this.store().messages().length);\n}\n// ag-ui : agent status component end\n",
  "src/app/features/attachments/media-chat.component.ts": "// attachments : enable attachments start\n/**\n * \"Enable attachments\", verbatim. Without `onUpload`, files are read as base64\n * and travel inline with the message.\n * https://docs.copilotkit.ai/angular/ms-agent-harness-dotnet/guides/threads-memory-attachments-headless\n */\n\nimport { Component } from '@angular/core';\nimport { CopilotChat, type AttachmentsConfig } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-media-chat',\n  imports: [CopilotChat],\n  template: ` <copilot-chat [attachments]=\"attachments\" /> `,\n})\nexport class MediaChatComponent {\n  // attachments : attachments config start\n  protected readonly attachments: AttachmentsConfig = {\n    enabled: true,\n    accept: 'image/*,application/pdf',\n    maxSize: 10 * 1024 * 1024,\n    onUploadFailed: (error) => {\n      console.error(error.reason, error.message);\n    },\n  };\n  // attachments : attachments config end\n}\n// attachments : enable attachments end\n",
  "src/app/features/chat-ui/chat-ui-demo.component.ts": "/**\n * Harness wrapper that mounts the guide's chat surfaces one at a time.\n *\n * The popup and the sidebar each get their own tab AND their own host\n * component. The guide declares both in a single component, but both render a\n * launcher at the same fixed coordinates, so mounting them together stacks two\n * launchers on one spot and the sidebar — rendered second — swallows every\n * click. The guide's combined component stays verbatim in\n * popup-sidebar.component.ts and is what the route page displays as source.\n *\n * Bindings on the split hosts are the guide's, unchanged.\n *\n * `.support-chat` is applied to the inline tab only. It is the scope class for\n * the guide's \"Scope CSS changes\" block, which repaints the message bubbles —\n * putting it on the shared host would tint the custom-message, popup, and\n * sidebar surfaces too, and each of those is meant to show its own default\n * styling.\n */\nimport { Component, signal } from '@angular/core';\n\nimport { CustomMessageChatComponent } from './custom-message-chat.component';\nimport { PopupOnlyComponent } from './popup-only.component';\nimport { SidebarOnlyComponent } from './sidebar-only.component';\nimport { SupportChatComponent } from './support-chat.component';\n\ntype Surface = 'inline' | 'custom-message' | 'popup' | 'sidebar';\n\n@Component({\n  selector: 'app-chat-ui-demo',\n  imports: [\n    SupportChatComponent,\n    CustomMessageChatComponent,\n    PopupOnlyComponent,\n    SidebarOnlyComponent,\n  ],\n  template: `\n    <div class=\"flex h-full flex-col gap-4 p-4\">\n      <div role=\"tablist\" aria-label=\"Chat surface\" class=\"flex flex-wrap gap-2\">\n        @for (tab of tabs; track tab.id) {\n          <button\n            type=\"button\"\n            role=\"tab\"\n            [attr.aria-selected]=\"surface() === tab.id\"\n            class=\"rounded-md border px-3 py-1.5 text-sm font-medium transition-colors\"\n            [class]=\"\n              surface() === tab.id\n                ? 'border-[var(--accent)] bg-[var(--accent)] text-white'\n                : 'border-[var(--line-strong)] bg-[var(--surface)] text-[var(--ink-soft)] hover:border-[var(--accent)] hover:text-[var(--accent-ink)]'\n            \"\n            (click)=\"surface.set(tab.id)\"\n          >\n            {{ tab.label }}\n          </button>\n        }\n      </div>\n\n      <div class=\"min-h-0 flex-1\">\n        @switch (surface()) {\n          @case ('inline') {\n            <!-- Scope class for the guide's CSS block — this tab only. -->\n            <div class=\"support-chat h-full\">\n              <app-support-chat />\n            </div>\n          }\n          @case ('custom-message') {\n            <div class=\"h-full\">\n              <app-custom-message-chat />\n            </div>\n          }\n          @case ('popup') {\n            <div class=\"space-y-3\">\n              <p class=\"text-sm text-[var(--ink-soft)]\">\n                <code>copilot-popup</code> opens from a floating launcher and\n                exposes a two-way <code>open</code> model, so the harness can\n                open it from here. It manages focus, closes on Escape, and\n                restores focus to the launcher.\n              </p>\n              <button\n                type=\"button\"\n                class=\"rounded-md border border-[var(--line-strong)] bg-[var(--surface)] px-3 py-1.5 text-sm font-medium text-[var(--ink-soft)] hover:border-[var(--accent)] hover:text-[var(--accent-ink)]\"\n                (click)=\"popupHost.popupOpen.set(!popupHost.popupOpen())\"\n              >\n                {{ popupHost.popupOpen() ? 'Close' : 'Open' }} popup\n              </button>\n              <app-popup-only #popupHost />\n            </div>\n          }\n          @case ('sidebar') {\n            <div class=\"space-y-3\">\n              <p class=\"text-sm text-[var(--ink-soft)]\">\n                <code>copilot-sidebar</code> is docked to the right at 480px.\n                Compact viewports render it as a modal even when\n                <code>mode</code> is <code>\"docked\"</code>, and only one open\n                docked sidebar can own the page margin at a time.\n              </p>\n              <button\n                type=\"button\"\n                class=\"rounded-md border border-[var(--line-strong)] bg-[var(--surface)] px-3 py-1.5 text-sm font-medium text-[var(--ink-soft)] hover:border-[var(--accent)] hover:text-[var(--accent-ink)]\"\n                (click)=\"sidebarHost.sidebarOpen.set(!sidebarHost.sidebarOpen())\"\n              >\n                {{ sidebarHost.sidebarOpen() ? 'Close' : 'Open' }} sidebar\n              </button>\n              <app-sidebar-only #sidebarHost />\n            </div>\n          }\n        }\n      </div>\n    </div>\n  `,\n})\nexport class ChatUiDemoComponent {\n  protected readonly surface = signal<Surface>('inline');\n  protected readonly tabs: ReadonlyArray<{ id: Surface; label: string }> = [\n    { id: 'inline', label: 'Inline chat' },\n    { id: 'custom-message', label: 'Custom assistant message' },\n    { id: 'popup', label: 'Popup' },\n    { id: 'sidebar', label: 'Sidebar' },\n  ];\n}\n",
  "src/app/features/chat-ui/custom-assistant-message.component.ts": "// chat ui : replace an assistant message start\n/**\n * \"Replace an assistant message\", verbatim.\n * https://docs.copilotkit.ai/angular/ms-agent-harness-dotnet/guides/chat-ui\n */\n\nimport { ChangeDetectionStrategy, Component, input } from '@angular/core';\n\ntype AssistantMessage = {\n  id: string;\n  role: 'assistant';\n  content?: string;\n};\n\n@Component({\n  selector: 'app-custom-assistant-message',\n  changeDetection: ChangeDetectionStrategy.OnPush,\n  template: `\n    <article class=\"answer\">\n      <span class=\"answer__label\">Assistant</span>\n      <p>{{ message().content }}</p>\n    </article>\n  `,\n})\nexport class CustomAssistantMessageComponent {\n  readonly message = input.required<AssistantMessage>();\n}\n// chat ui : replace an assistant message end\n",
  "src/app/features/chat-ui/custom-message-chat.component.ts": "// chat ui : replace an assistant message component start\n/**\n * The second `SupportChatComponent` from \"Replace an assistant message\",\n * verbatim except for the class name and selector — the guide gives two\n * different components the same name and selector, and both are mounted here.\n * https://docs.copilotkit.ai/angular/ms-agent-harness-dotnet/guides/chat-ui\n */\n\nimport { Component } from '@angular/core';\nimport { CopilotChat } from '@copilotkit/angular';\n\nimport { CustomAssistantMessageComponent } from './custom-assistant-message.component';\n\n@Component({\n  selector: 'app-custom-message-chat',\n  imports: [CopilotChat],\n  template: `\n    <copilot-chat\n      [assistantMessageComponent]=\"assistantMessageComponent\"\n      assistantMessageClass=\"support-answer\"\n    />\n  `,\n})\nexport class CustomMessageChatComponent {\n  protected readonly assistantMessageComponent =\n    CustomAssistantMessageComponent;\n}\n// chat ui : replace an assistant message component end\n",
  "src/app/features/chat-ui/popup-only.component.ts": "// chat ui : use a popup start\n/**\n * The popup half of the guide's \"Use a popup or sidebar\" sample, on its own\n * host. Bindings are the guide's, unchanged.\n *\n * The guide declares `copilot-popup` and `copilot-sidebar` in one component.\n * Both render a launcher at the same fixed coordinates\n * (`right: max(1.5rem, …); bottom: max(1.5rem, …)`), so mounting them together\n * stacks two launchers on one spot and the sidebar — rendered second — takes\n * every click. Splitting them is what makes each surface separately testable;\n * the combined component is kept verbatim in popup-sidebar.component.ts and\n * shown as the source on the route page.\n *\n * https://docs.copilotkit.ai/angular/ms-agent-harness-dotnet/guides/chat-ui\n */\n\nimport { Component, signal } from '@angular/core';\nimport { CopilotPopup } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-popup-only',\n  imports: [CopilotPopup],\n  template: `\n    <copilot-popup\n      [(open)]=\"popupOpen\"\n      title=\"Support assistant\"\n      [clickOutsideToClose]=\"true\"\n    />\n  `,\n})\nexport class PopupOnlyComponent {\n  readonly popupOpen = signal(false);\n}\n// chat ui : use a popup end\n",
  "src/app/features/chat-ui/popup-sidebar.component.ts": "// chat ui : use a popup or sidebar start\n/**\n * \"Use a popup or sidebar\", verbatim except for the class name and selector\n * (the guide mounts it as `AppComponent` / `app-root`).\n * https://docs.copilotkit.ai/angular/ms-agent-harness-dotnet/guides/chat-ui\n */\n\nimport { Component, signal } from '@angular/core';\nimport { CopilotPopup, CopilotSidebar } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-popup-sidebar',\n  imports: [CopilotPopup, CopilotSidebar],\n  template: `\n    <copilot-popup\n      [(open)]=\"popupOpen\"\n      title=\"Support assistant\"\n      [clickOutsideToClose]=\"true\"\n    />\n\n    <copilot-sidebar\n      [(open)]=\"sidebarOpen\"\n      mode=\"docked\"\n      position=\"right\"\n      title=\"Workspace assistant\"\n      [width]=\"480\"\n    />\n  `,\n})\nexport class PopupSidebarComponent {\n  readonly popupOpen = signal(false);\n  readonly sidebarOpen = signal(false);\n}\n// chat ui : use a popup or sidebar end\n",
  "src/app/features/chat-ui/sidebar-only.component.ts": "// chat ui : use a sidebar start\n/**\n * The sidebar half of the guide's \"Use a popup or sidebar\" sample, on its own\n * host. Bindings are the guide's, unchanged.\n *\n * See popup-only.component.ts for why the guide's combined component is split\n * for the demo: both surfaces render a launcher at the same fixed coordinates.\n *\n * https://docs.copilotkit.ai/angular/ms-agent-harness-dotnet/guides/chat-ui\n */\n\nimport { Component, signal } from '@angular/core';\nimport { CopilotSidebar } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-sidebar-only',\n  imports: [CopilotSidebar],\n  template: `\n    <copilot-sidebar\n      [(open)]=\"sidebarOpen\"\n      mode=\"docked\"\n      position=\"right\"\n      title=\"Workspace assistant\"\n      [width]=\"480\"\n    />\n  `,\n})\nexport class SidebarOnlyComponent {\n  readonly sidebarOpen = signal(false);\n}\n// chat ui : use a sidebar end\n",
  "src/app/features/chat-ui/support-chat.component.ts": "// chat ui : add an inline chat start\n/**\n * \"Add an inline chat\", verbatim.\n * https://docs.copilotkit.ai/angular/ms-agent-harness-dotnet/guides/chat-ui\n *\n * `agentId=\"support\"` resolves because the runtime registers a `support` agent\n * alongside `default` (see frontend/server.ts).\n */\n\nimport { ChangeDetectionStrategy, Component } from '@angular/core';\nimport { CopilotChat } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-support-chat',\n  imports: [CopilotChat],\n  changeDetection: ChangeDetectionStrategy.OnPush,\n  template: `\n    <section class=\"chat-shell\" aria-label=\"Support assistant\">\n      <copilot-chat agentId=\"support\" />\n    </section>\n  `,\n  styles: `\n    .chat-shell {\n      height: min(48rem, 80vh);\n      overflow: hidden;\n      border: 1px solid #dbe3eb;\n      border-radius: 1rem;\n    }\n  `,\n})\nexport class SupportChatComponent {}\n// chat ui : add an inline chat end\n",
  "src/app/features/copilot-runtime/multi-agent-chat.component.ts": "/**\n * Two agents behind the one Copilot Runtime in server.ts, from\n * https://docs.copilotkit.ai/angular/ms-agent-harness-dotnet/copilot-runtime\n *\n * - \"The Default Agent\": a copilot-chat with no agentId resolves the\n *   `default` key.\n * - \"Which name identifies an agent\": the guide's\n *   `<copilot-chat agentId=\"my_agent\" />`, addressed instead to a key this\n *   runtime actually registers — `research-agent`. The key is the only name\n *   the frontend can ask for; the .NET agent's own `name` is never used for\n *   routing.\n *\n * The side-by-side layout is this harness's own; it is not in the guide.\n */\nimport { Component } from '@angular/core';\nimport { CopilotChat } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-multi-agent-chat',\n  imports: [CopilotChat],\n  template: `\n    <div style=\"display: flex; height: 100%; gap: 1rem; padding: 1rem\">\n      <section style=\"flex: 1; min-width: 0; display: flex; flex-direction: column\">\n        <h2 style=\"margin: 0 0 0.5rem; font-size: 0.875rem; font-weight: 600\">\n          default\n        </h2>\n        <div style=\"flex: 1; min-height: 0\">\n          <!-- copilot runtime : default agent start -->\n          <copilot-chat />\n          <!-- copilot runtime : default agent end -->\n        </div>\n      </section>\n      <section style=\"flex: 1; min-width: 0; display: flex; flex-direction: column\">\n        <h2 style=\"margin: 0 0 0.5rem; font-size: 0.875rem; font-weight: 600\">\n          research-agent\n        </h2>\n        <div style=\"flex: 1; min-height: 0\">\n          <!-- copilot runtime : agent by key start -->\n          <copilot-chat agentId=\"research-agent\" />\n          <!-- copilot runtime : agent by key end -->\n        </div>\n      </section>\n    </div>\n  `,\n})\nexport class MultiAgentChatComponent {}\n",
  "src/app/features/headless/headless-chat.component.ts": "// headless : build a headless chat start\n/**\n * \"Build a headless chat\", verbatim. No CopilotKit chrome: the transcript and\n * composer are hand-written over `injectAgentStore`, and the run is driven\n * through `CopilotKitCore.runAgent`.\n * https://docs.copilotkit.ai/angular/ms-agent-harness-dotnet/guides/threads-memory-attachments-headless\n */\n\nimport { Component, inject, signal } from '@angular/core';\nimport { CopilotKit, injectAgentStore } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-headless-chat',\n  template: `\n    <div aria-live=\"polite\">\n      @for (message of store().messages(); track message.id) {\n        <article [attr.data-role]=\"message.role\">\n          {{ message.content }}\n        </article>\n      }\n      @if (store().isRunning()) {\n        <p>Agent is working…</p>\n      }\n    </div>\n\n    <textarea\n      aria-label=\"Message\"\n      [value]=\"draft()\"\n      (input)=\"updateDraft($event)\"\n    ></textarea>\n    <button\n      type=\"button\"\n      [disabled]=\"store().isRunning() || !draft().trim()\"\n      (click)=\"send()\"\n    >\n      Send\n    </button>\n  `,\n})\nexport class HeadlessChatComponent {\n  private readonly copilotKit = inject(CopilotKit);\n  // headless : inject agent store start\n  readonly store = injectAgentStore('default');\n  // headless : inject agent store end\n  readonly draft = signal('');\n\n  protected updateDraft(event: Event): void {\n    this.draft.set((event.target as HTMLTextAreaElement).value);\n  }\n\n  protected async send(): Promise<void> {\n    const content = this.draft().trim();\n    if (!content || this.store().isRunning()) return;\n\n    const agent = this.store().agent;\n    agent.addMessage({\n      id: crypto.randomUUID(),\n      role: 'user',\n      content,\n    });\n    this.draft.set('');\n    // headless : run agent start\n    await this.copilotKit.core.runAgent({ agent });\n    // headless : run agent end\n  }\n}\n// headless : build a headless chat end\n",
  "src/app/features/hitl/approval-card.component.ts": "// human in the loop : register a decision tool renderer start\n/**\n * \"Register a decision tool\" renderer, verbatim.\n * https://docs.copilotkit.ai/angular/ms-agent-harness-dotnet/guides/human-in-the-loop\n */\n\nimport { Component, input } from '@angular/core';\nimport {\n  type HumanInTheLoopToolCall,\n  type HumanInTheLoopToolRenderer,\n} from '@copilotkit/angular';\n\ntype ApprovalArgs = {\n  action: string;\n  reason: string;\n};\n\n@Component({\n  selector: 'app-approval-card',\n  template: `\n    @let call = toolCall();\n    <article>\n      <h3>Approve {{ call.args.action ?? \"this action\" }}?</h3>\n      <p>{{ call.args.reason }}</p>\n\n      @if (call.status !== \"complete\") {\n        <button type=\"button\" (click)=\"call.respond({ approved: true })\">\n          Approve\n        </button>\n        <button type=\"button\" (click)=\"call.respond({ approved: false })\">\n          Reject\n        </button>\n      }\n    </article>\n  `,\n})\nexport class ApprovalCardComponent\n  implements HumanInTheLoopToolRenderer<ApprovalArgs>\n{\n  readonly toolCall = input.required<HumanInTheLoopToolCall<ApprovalArgs>>();\n}\n// human in the loop : register a decision tool renderer end\n",
  "src/app/features/hitl/approval-tools.service.ts": "// human in the loop : register a decision tool service start\n/**\n * \"Register the tool from the component or service that owns the decision UI\",\n * verbatim. There is no handler — CopilotKit supplies one that waits for\n * `respond`, returns the decision to the agent, and continues the run.\n * https://docs.copilotkit.ai/angular/ms-agent-harness-dotnet/guides/human-in-the-loop\n */\n\nimport { Injectable } from '@angular/core';\nimport { registerHumanInTheLoop } from '@copilotkit/angular';\nimport { z } from 'zod';\n\nimport { ApprovalCardComponent } from './approval-card.component';\n\n@Injectable()\nexport class ApprovalToolsService {\n  constructor() {\n    // human in the loop : register human in the loop tool start\n    registerHumanInTheLoop({\n      name: 'requestApproval',\n      description: 'Ask the user before a consequential action',\n      parameters: z.object({\n        action: z.string(),\n        reason: z.string(),\n      }),\n      component: ApprovalCardComponent,\n    });\n    // human in the loop : register human in the loop tool end\n  }\n}\n// human in the loop : register a decision tool service end\n",
  "src/app/features/hitl/hitl-chat.component.ts": "// human in the loop : hitl chat start\n/**\n * Puts the guide's three human-in-the-loop paths side by side: the decision\n * tool (registered by ApprovalToolsService, rendered inside the chat's\n * tool-call flow), the headless interrupt controller, and the store's own\n * controller — the last two rendered outside the chat and pointed at different\n * agents, as the guide's warning requires.\n * https://docs.copilotkit.ai/angular/ms-agent-harness-dotnet/guides/human-in-the-loop\n *\n * Injecting ApprovalToolsService is what constructs it, and construction is\n * what performs the `registerHumanInTheLoop` call.\n */\n\nimport { Component, inject } from '@angular/core';\nimport { CopilotChat } from '@copilotkit/angular';\n\nimport { ApprovalToolsService } from './approval-tools.service';\nimport { InterruptPanelComponent } from './interrupt-panel.component';\nimport { TicketApprovalComponent } from './ticket-approval.component';\n\n@Component({\n  selector: 'app-hitl-chat',\n  imports: [CopilotChat, InterruptPanelComponent, TicketApprovalComponent],\n  providers: [ApprovalToolsService],\n  template: `\n    <div style=\"display: flex; flex-direction: column; height: 100%\">\n      <app-interrupt-panel />\n      <app-ticket-approval />\n      <div style=\"flex: 1; min-height: 0\">\n        <copilot-chat />\n      </div>\n    </div>\n  `,\n})\nexport class HitlChatComponent {\n  private readonly approvalTools = inject(ApprovalToolsService);\n}\n// human in the loop : hitl chat end\n",
  "src/app/features/hitl/interrupt-panel.component.ts": "// human in the loop : handle an interrupt start\n/**\n * \"Handle an interrupt\", verbatim. The controller is headless, so this panel\n * renders nothing until the backend emits an AG-UI interrupt.\n * https://docs.copilotkit.ai/angular/ms-agent-harness-dotnet/guides/human-in-the-loop\n */\n\nimport { Component } from '@angular/core';\nimport { injectInterrupt } from '@copilotkit/angular';\n\ntype ReviewRequest = {\n  title?: string;\n  choices?: Array<{ id: string; label: string }>;\n};\n\n@Component({\n  selector: 'app-interrupt-panel',\n  template: `\n    @if (controller.event(); as event) {\n      @let request = asReviewRequest(event.value);\n      <section aria-labelledby=\"review-title\">\n        <h2 id=\"review-title\">{{ request.title ?? \"Review required\" }}</h2>\n\n        @for (choice of request.choices ?? []; track choice.id) {\n          <button type=\"button\" (click)=\"resolve(choice.id)\">\n            {{ choice.label }}\n          </button>\n        }\n\n        <button type=\"button\" (click)=\"cancel()\">Cancel</button>\n      </section>\n    }\n\n    @if (controller.error()) {\n      <p role=\"alert\">The decision could not be submitted.</p>\n    }\n  `,\n})\nexport class InterruptPanelComponent {\n  // DIVERGENCE RESOLVED at @copilotkit/angular@0.4.0 — the doc's own form runs.\n  //\n  // The doc's snippet passes the agent id as a string:\n  //\n  //     injectInterrupt<ReviewRequest>('default');\n  //\n  // That did not compile against @copilotkit/angular@0.3.1, whose declaration\n  // took an options object and had no string overload:\n  //\n  //     declare function injectInterrupt<TValue, TResult>(\n  //       options?: InjectInterruptOptions<TValue, TResult>\n  //     ): InterruptController<TValue, TResult>;\n  //\n  //   TS2559: Type '\"default\"' has no properties in common with type\n  //           'InjectInterruptOptions<ReviewRequest, never>'\n  //\n  // This file carried the object form for as long as that was true, because one\n  // compile error blocks every recording, not just this page. 0.4.0 publishes\n  // the string-first overload:\n  //\n  //     declare function injectInterrupt<TValue, TResult>(\n  //       agentId?: InterruptAgentId,\n  //       options?: Omit<InjectInterruptOptions<TValue, TResult>, \"agentId\">\n  //     ): InterruptController<TValue, TResult>;\n  //\n  // The finding stands as a doc-ahead-of-release defect — the page carried no\n  // version note while the snippet was uncompilable — but it no longer blocks.\n  //\n  // human in the loop : inject interrupt start\n  protected readonly controller = injectInterrupt<ReviewRequest>('default');\n  // human in the loop : inject interrupt end\n\n  protected asReviewRequest(value: unknown): ReviewRequest {\n    return typeof value === 'object' && value !== null\n      ? (value as ReviewRequest)\n      : {};\n  }\n\n  protected resolve(choiceId: string): void {\n    this.controller.resolve({ choiceId }).catch(() => undefined);\n  }\n\n  protected cancel(): void {\n    this.controller.cancel().catch(() => undefined);\n  }\n}\n// human in the loop : handle an interrupt end\n",
  "src/app/features/hitl/ticket-approval.component.ts": "// human in the loop : ticket approval start\n/**\n * \"Handle an interrupt from the store\", verbatim.\n * https://docs.copilotkit.ai/angular/ms-agent-harness-dotnet/guides/human-in-the-loop\n *\n * Unimplementable until now: `AgentStore` shipped only `agent`, `isRunning`,\n * `messages` and `state` in `@copilotkit/angular@0.3.1`, so\n * `store().interruptController` did not exist for as long as the section\n * described it. `0.4.0` adds `readonly interruptController: InterruptController`\n * and the snippet compiles as published.\n *\n * One deviation: the doc injects the store for an agent named `ticketing`. No\n * such agent is registered here, and an unknown id resolves to a store whose\n * controller never sees an event — which would make this component look healthy\n * while testing nothing. It uses `support`, the second agent this repo's\n * runtime registers, which also keeps it off `default` and so honours the\n * guide's own warning against pointing `injectInterrupt` and\n * `store().interruptController` at one decision: the sibling\n * `app-interrupt-panel` holds `default`.\n */\n\nimport { Component } from '@angular/core';\nimport { injectAgentStore } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-ticket-approval',\n  template: `\n    @let interrupts = store().interruptController;\n\n    @if (interrupts.hasInterrupt()) {\n      <section>\n        <p>{{ interrupts.interrupt()?.message }}</p>\n        <button type=\"button\" (click)=\"interrupts.resolve({ approved: true })\">\n          Approve\n        </button>\n        <button type=\"button\" (click)=\"interrupts.cancel()\">Reject</button>\n      </section>\n    }\n  `,\n})\nexport class TicketApprovalComponent {\n  protected readonly store = injectAgentStore('support');\n}\n// human in the loop : ticket approval end\n",
  "src/app/features/media/voice-chat.component.ts": "// voice & multimodal : accept voice input and configure attachments start\n/**\n * \"Configure attachments\", verbatim: the guide's `MULTIMODAL_ATTACHMENTS`\n * config bound to the chat exactly as its `media-chat.component.html` snippet\n * shows. The microphone control needs no option — it is always present.\n * https://docs.copilotkit.ai/angular/ms-agent-harness-dotnet/guides/voice-multimodal\n */\n\nimport { Component } from '@angular/core';\nimport { CopilotChat, type AttachmentsConfig } from '@copilotkit/angular';\n\n// voice & multimodal : configure attachments start\nconst MULTIMODAL_ATTACHMENTS: AttachmentsConfig = {\n  enabled: true,\n  accept: 'image/*,application/pdf',\n  maxSize: 10 * 1024 * 1024,\n};\n// voice & multimodal : configure attachments end\n\n@Component({\n  selector: 'app-voice-chat',\n  imports: [CopilotChat],\n  template: `\n    <div style=\"height: 100%\">\n      <copilot-chat [attachments]=\"multimodalAttachments\" />\n    </div>\n  `,\n})\nexport class VoiceChatComponent {\n  protected readonly multimodalAttachments = MULTIMODAL_ATTACHMENTS;\n}\n// voice & multimodal : accept voice input and configure attachments end\n",
  "src/app/features/memory/memory-demo.component.ts": "/**\n * Harness wrapper mounting the guide's memory list beside a chat, so the\n * `isAvailable()` gate can be observed against a live runtime.\n */\nimport { Component } from '@angular/core';\nimport { CopilotChat } from '@copilotkit/angular';\n\nimport { MemoryListComponent } from './memory-list.component';\n\n@Component({\n  selector: 'app-memory-demo',\n  imports: [CopilotChat, MemoryListComponent],\n  template: `\n    <div class=\"flex h-full gap-4 p-4\">\n      <section\n        class=\"w-80 shrink-0 overflow-y-auto rounded-lg border border-slate-200 bg-white p-4\"\n      >\n        <h2 class=\"mb-2 text-sm font-semibold text-slate-900\">\n          injectMemories\n        </h2>\n        <app-memory-list />\n      </section>\n      <div class=\"min-w-0 flex-1\">\n        <copilot-chat />\n      </div>\n    </div>\n  `,\n})\nexport class MemoryDemoComponent {}\n",
  "src/app/features/memory/memory-list.component.ts": "// memory : read and manage memory start\n/**\n * \"Configure attachments\", verbatim: the guide's `MULTIMODAL_ATTACHMENTS`\n * config bound to the chat exactly as its `media-chat.component.html` snippet\n * shows. The microphone control needs no option — it is always present.\n * https://docs.copilotkit.ai/angular/ms-agent-harness-dotnet/guides/voice-multimodal\n */\n\nimport { Component } from '@angular/core';\nimport { injectMemories } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-memory-list',\n  template: `\n    @if (!memory.isAvailable()) {\n      <p>Memory is not available for this runtime.</p>\n    } @else {\n      @for (item of memory.memories(); track item.id) {\n        <article>\n          <p>{{ item.content }}</p>\n          <button type=\"button\" (click)=\"remove(item.id)\">Forget</button>\n        </article>\n      }\n    }\n  `,\n})\nexport class MemoryListComponent {\n  // memory : inject memories start\n  readonly memory = injectMemories();\n  // memory : inject memories end\n\n  protected remove(id: string): void {\n    this.memory.removeMemory(id).catch(() => undefined);\n  }\n\n  protected addPreference(): void {\n    this.memory\n      .addMemory({\n        kind: 'operational',\n        content: 'Prefer concise status updates.',\n      })\n      .catch(() => undefined);\n  }\n}\n// memory : read and manage memory end\n",
  "src/app/features/quickstart/quickstart-chat.ts": "// quickstart : add the chat ui start\nimport { Component } from '@angular/core';\nimport { CopilotChat } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-quickstart-chat',\n  imports: [CopilotChat],\n  template: `\n    <div style=\"height: 100vh\">\n      <copilot-chat />\n    </div>\n  `,\n})\nexport class QuickstartChat {}\n// quickstart : add the chat ui end\n",
  "src/app/features/shared-state/account-context.component.ts": "// shared state : send read-only application context start\n/**\n * \"Send read-only application context\", verbatim. The accessor form keeps the\n * signal reads reactive, so changing the timezone re-registers the context.\n * https://docs.copilotkit.ai/angular/ms-agent-harness-dotnet/guides/shared-state\n */\n\nimport { Component, signal } from '@angular/core';\nimport { connectAgentContext } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-account-context',\n  template: `\n    <br>\n    <button type=\"button\" (click)=\"timezone.set('Europe/London')\">\n      Use London time\n    </button>\n  `,\n})\nexport class AccountContextComponent {\n  readonly userName = signal('Ada');\n  readonly timezone = signal('America/Los_Angeles');\n\n  constructor() {\n    connectAgentContext(() => ({\n      description: 'Current account and timezone',\n      value: JSON.stringify({\n        userName: this.userName(),\n        timezone: this.timezone(),\n      }),\n    }));\n  }\n}\n// shared state : send read-only application context end\n",
  "src/app/features/shared-state/selection-context.component.ts": "// shared state : bind context in a template start\n/**\n * \"Bind context in a template\", verbatim. The directive registers on first\n * render, so it must not be rendered before the context is complete.\n * https://docs.copilotkit.ai/angular/ms-agent-harness-dotnet/guides/shared-state\n */\n\nimport { Component, computed, signal } from '@angular/core';\nimport { CopilotKitAgentContext } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-selection-context',\n  imports: [CopilotKitAgentContext],\n  template: ` <div [copilotkitAgentContext]=\"selectionContext()\"></div> `,\n})\nexport class SelectionContextComponent {\n  readonly selectedId = signal('record-42');\n  readonly selectionContext = computed(() => ({\n    description: 'The record selected in the application',\n    value: this.selectedId(),\n  }));\n}\n// shared state : bind context in a template end\n",
  "src/app/features/shared-state/shared-state-chat.component.ts": "// shared state : shared state chat start\n/**\n * Mounts the guide's three surfaces against one chat: the read/write state\n * panel, the accessor-based context, and the directive-based context.\n * https://docs.copilotkit.ai/angular/ms-agent-harness-dotnet/guides/shared-state\n */\n\nimport { Component } from '@angular/core';\nimport { CopilotChat } from '@copilotkit/angular';\n\nimport { AccountContextComponent } from './account-context.component';\nimport { SelectionContextComponent } from './selection-context.component';\nimport { WorkspaceComponent } from './workspace.component';\n\n@Component({\n  selector: 'app-shared-state-chat',\n  imports: [\n    CopilotChat,\n    WorkspaceComponent,\n    AccountContextComponent,\n    SelectionContextComponent,\n  ],\n  template: `\n    <div style=\"display: flex; height: 100%; gap: 1rem\">\n      <div style=\"width: 20rem; overflow-y: auto; padding: 1rem\">\n        <app-workspace />\n        <app-account-context />\n        <app-selection-context />\n      </div>\n      <div style=\"flex: 1; min-width: 0\">\n        <copilot-chat />\n      </div>\n    </div>\n  `,\n})\nexport class SharedStateChatComponent {}\n// shared state : shared state chat end\n",
  "src/app/features/shared-state/workspace.component.ts": "// shared state : read and write agent state start\n/**\n * \"Read agent state\", verbatim. Reads through `store().state()` so Angular\n * tracks changes; writes through the plain AG-UI agent at `store().agent`.\n * https://docs.copilotkit.ai/angular/ms-agent-harness-dotnet/guides/shared-state\n */\n\nimport { Component, computed } from '@angular/core';\nimport { injectAgentStore } from '@copilotkit/angular';\n\ntype WorkspaceState = {\n  notes: string[];\n  priority: 'low' | 'normal' | 'high';\n};\n\nconst EMPTY_STATE: WorkspaceState = {\n  notes: [],\n  priority: 'normal',\n};\n\n@Component({\n  selector: 'app-workspace',\n  template: `\n    <p>Priority: {{ state().priority }}</p>\n    <ul>\n      @for (note of state().notes; track note) {\n        <li>{{ note }}</li>\n      }\n    </ul>\n    <button type=\"button\" (click)=\"setPriority('high')\">\n      Mark high priority\n    </button>\n    <br>\n     <button type=\"button\" (click)=\"setPriority('low')\">\n      Mark low priority\n    </button>\n  `,\n})\nexport class WorkspaceComponent {\n  readonly store = injectAgentStore('default');\n  readonly state = computed(\n    () => (this.store().state() as WorkspaceState | undefined) ?? EMPTY_STATE,\n  );\n\n  protected setPriority(priority: WorkspaceState['priority']): void {\n    const agent = this.store().agent;\n    const current = (agent.state as WorkspaceState | undefined) ?? EMPTY_STATE;\n    agent.setState({ ...current, priority });\n  }\n}\n// shared state : read and write agent state end\n",
  "src/app/features/subagents/subagent-cards.ts": "/**\n * Sub-agent transcript card and delegation log for\n * https://docs.copilotkit.ai/angular/ms-agent-harness-dotnet/multi-agent/subagents\n *\n * The page renders these without showing them. This is the\n * `SubAgentActivityCard` and `DelegationLogComponent` half of the Angular\n * Showcase's features/agent-state/agent-state-cards.ts, unchanged; the planner\n * card belongs to a different demo and is left out.\n */\nimport {\n  ChangeDetectionStrategy,\n  Component,\n  computed,\n  input,\n} from \"@angular/core\";\nimport type { AngularToolCall } from \"@copilotkit/angular\";\n\nimport type { Delegation, SubAgentName } from \"./subagent-model\";\n\nconst SUB_AGENT_META: Readonly<\n  Record<\n    SubAgentName,\n    {\n      label: string;\n      testId: string;\n      delegationTestId: string;\n      action: string;\n    }\n  >\n> = {\n  research_agent: {\n    label: \"Researcher\",\n    testId: \"subagent-card-researcher\",\n    delegationTestId: \"subagent-delegation-researcher\",\n    action: \"gathering facts\",\n  },\n  writing_agent: {\n    label: \"Writer\",\n    testId: \"subagent-card-writer\",\n    delegationTestId: \"subagent-delegation-writer\",\n    action: \"drafting prose\",\n  },\n  critique_agent: {\n    label: \"Critic\",\n    testId: \"subagent-card-critic\",\n    delegationTestId: \"subagent-delegation-critic\",\n    action: \"reviewing the draft\",\n  },\n};\n\n@Component({\n  selector: \"showcase-subagent-activity-card\",\n  changeDetection: ChangeDetectionStrategy.OnPush,\n  template: `\n    <article\n      class=\"subagent-card\"\n      [attr.data-testid]=\"meta().testId\"\n      [attr.data-sub-agent]=\"subAgent()\"\n      [attr.data-status]=\"toolCall().status\"\n    >\n      <header>\n        <strong>{{ meta().label }}</strong>\n        <span>{{ complete() ? \"Complete\" : \"Working\" }}</span>\n      </header>\n      <p><b>Task:</b> {{ toolCall().args.task || \"Receiving task…\" }}</p>\n      @if (complete()) {\n        <p data-testid=\"subagent-result\"><b>Result:</b> {{ toolCall().result }}</p>\n      } @else {\n        <p>{{ meta().label }} is {{ meta().action }}…</p>\n      }\n    </article>\n  `,\n  styles: `\n    :host {\n      display: block;\n      margin: 0.75rem 0;\n    }\n    .subagent-card {\n      overflow: hidden;\n      border: 1px solid #c7d2fe;\n      border-radius: 1rem;\n      color: #18253a;\n      background: #f8faff;\n      box-shadow: 0 6px 20px rgb(49 46 129 / 8%);\n    }\n    header {\n      display: flex;\n      justify-content: space-between;\n      gap: 1rem;\n      padding: 0.7rem 0.9rem;\n      border-bottom: 1px solid #dbe3f0;\n      background: #eef2ff;\n    }\n    header span {\n      color: #475569;\n      font-size: 0.7rem;\n      font-weight: 700;\n      letter-spacing: 0.08em;\n      text-transform: uppercase;\n    }\n    p {\n      margin: 0;\n      padding: 0.7rem 0.9rem;\n      white-space: pre-wrap;\n      font-size: 0.8rem;\n      line-height: 1.5;\n    }\n    p + p {\n      padding-top: 0;\n    }\n  `,\n})\nexport class SubAgentActivityCard {\n  readonly toolCall = input.required<AngularToolCall<{ task: string }>>();\n  protected readonly subAgent = computed(() => {\n    const name = this.toolCall().name;\n    return isSubAgentName(name) ? name : \"research_agent\";\n  });\n  protected readonly meta = computed(() => SUB_AGENT_META[this.subAgent()]);\n  protected readonly complete = computed(\n    () => this.toolCall().status === \"complete\",\n  );\n}\n\nfunction isSubAgentName(value: unknown): value is SubAgentName {\n  return (\n    value === \"research_agent\" ||\n    value === \"writing_agent\" ||\n    value === \"critique_agent\"\n  );\n}\n\n@Component({\n  selector: \"showcase-delegation-log\",\n  changeDetection: ChangeDetectionStrategy.OnPush,\n  template: `\n    <section class=\"delegation-log\" data-testid=\"delegation-log\">\n      <header>\n        <div>\n          <p>Supervisor</p>\n          <h1>Sub-agent delegations</h1>\n        </div>\n        <span data-testid=\"delegation-count\">{{ delegations().length }} calls</span>\n      </header>\n      <div class=\"role-row\" aria-label=\"Available sub-agents\">\n        @for (role of roles; track role.subAgent) {\n          <span [attr.data-fired]=\"called(role.subAgent)\">{{ role.label }}</span>\n        }\n      </div>\n      @if (delegations().length === 0) {\n        <p class=\"empty\">\n          Ask the supervisor to research, write, and critique a task.\n        </p>\n      } @else {\n        <ol>\n          @for (\n            delegation of delegations();\n            track delegation.id;\n            let index = $index\n          ) {\n            <li\n              [attr.data-testid]=\"testIdFor(delegation.subAgent)\"\n              [attr.data-status]=\"delegation.status\"\n            >\n              <strong>{{ index + 1 }}. {{ labelFor(delegation.subAgent) }}</strong>\n              <span>{{ delegation.status }}</span>\n              <p>{{ delegation.task }}</p>\n              <blockquote>{{ delegation.result }}</blockquote>\n            </li>\n          }\n        </ol>\n      }\n    </section>\n  `,\n  styles: `\n    :host {\n      display: block;\n      min-width: 0;\n    }\n    .delegation-log {\n      overflow: hidden;\n      border: 1px solid #d8e0ea;\n      border-radius: 1rem;\n      background: #fff;\n      box-shadow: 0 12px 34px rgb(30 49 73 / 8%);\n    }\n    header {\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      gap: 1rem;\n      padding: 1rem;\n      border-bottom: 1px solid #e2e8f0;\n    }\n    header p,\n    header h1 {\n      margin: 0;\n    }\n    header p {\n      color: #6366f1;\n      font-size: 0.7rem;\n      font-weight: 750;\n      letter-spacing: 0.12em;\n      text-transform: uppercase;\n    }\n    header h1 {\n      margin-top: 0.2rem;\n      color: #152238;\n      font-size: 1.1rem;\n    }\n    header span {\n      color: #64748b;\n      font-size: 0.75rem;\n    }\n    .role-row {\n      display: flex;\n      flex-wrap: wrap;\n      gap: 0.5rem;\n      padding: 0.75rem 1rem;\n      border-bottom: 1px solid #e2e8f0;\n    }\n    .role-row span {\n      padding: 0.3rem 0.55rem;\n      border: 1px solid #cbd5e1;\n      border-radius: 999px;\n      color: #64748b;\n      font-size: 0.72rem;\n    }\n    .role-row span[data-fired=\"true\"] {\n      border-color: #818cf8;\n      color: #3730a3;\n      background: #eef2ff;\n    }\n    .empty {\n      margin: 0;\n      padding: 1rem;\n      color: #64748b;\n      font-size: 0.85rem;\n    }\n    ol {\n      display: grid;\n      gap: 0.75rem;\n      margin: 0;\n      padding: 1rem;\n      list-style: none;\n    }\n    li {\n      padding: 0.8rem;\n      border: 1px solid #e2e8f0;\n      border-radius: 0.75rem;\n      background: #f8fafc;\n    }\n    li > span {\n      float: right;\n      color: #15803d;\n      font-size: 0.7rem;\n      text-transform: uppercase;\n    }\n    li p,\n    blockquote {\n      margin: 0.5rem 0 0;\n      color: #475569;\n      font-size: 0.78rem;\n      line-height: 1.45;\n    }\n    blockquote {\n      padding: 0.65rem;\n      border-radius: 0.5rem;\n      background: #fff;\n    }\n  `,\n})\nexport class DelegationLogComponent {\n  readonly delegations = input.required<Delegation[]>();\n  protected readonly roles = [\n    { subAgent: \"research_agent\" as const, label: \"Researcher\" },\n    { subAgent: \"writing_agent\" as const, label: \"Writer\" },\n    { subAgent: \"critique_agent\" as const, label: \"Critic\" },\n  ];\n\n  protected called(subAgent: SubAgentName): boolean {\n    return this.delegations().some(\n      (delegation) => delegation.subAgent === subAgent,\n    );\n  }\n\n  protected labelFor(subAgent: SubAgentName): string {\n    return SUB_AGENT_META[subAgent].label;\n  }\n\n  /** Resolve a delegation-log identity distinct from transcript tool cards. */\n  protected testIdFor(subAgent: SubAgentName): string {\n    return SUB_AGENT_META[subAgent].delegationTestId;\n  }\n}\n",
  "src/app/features/subagents/subagent-model.ts": "/**\n * Delegation-log model for\n * https://docs.copilotkit.ai/angular/ms-agent-harness-dotnet/multi-agent/subagents\n *\n * The page uses `readDelegations` and `SubAgentName` without showing them.\n * This is the sub-agent half of the Angular Showcase's\n * features/agent-state/agent-state-model.ts, unchanged; the planner (`steps`)\n * half belongs to a different demo and is left out.\n */\nexport type SubAgentName =\n  | \"research_agent\"\n  | \"writing_agent\"\n  | \"critique_agent\";\n\nexport interface Delegation {\n  id: string;\n  subAgent: SubAgentName;\n  task: string;\n  status: \"completed\";\n  result: string;\n}\n\n/** Read completed supervisor delegations from append-only agent state. */\nexport function readDelegations(state: unknown): Delegation[] {\n  const delegations = readArraySlot(state, \"delegations\");\n  return delegations.flatMap((candidate) => {\n    if (!isRecord(candidate)) return [];\n    const { id, sub_agent: subAgent, task, status, result } = candidate;\n    if (\n      typeof id !== \"string\" ||\n      !isSubAgentName(subAgent) ||\n      typeof task !== \"string\" ||\n      status !== \"completed\" ||\n      typeof result !== \"string\"\n    ) {\n      return [];\n    }\n    return [{ id, subAgent, task, status, result }];\n  });\n}\n\nfunction readArraySlot(state: unknown, slot: string): unknown[] {\n  if (!isRecord(state)) return [];\n  const value = state[slot];\n  return Array.isArray(value) ? value : [];\n}\n\nfunction isRecord(value: unknown): value is Record<string, unknown> {\n  return typeof value === \"object\" && value !== null;\n}\n\nfunction isSubAgentName(value: unknown): value is SubAgentName {\n  return (\n    value === \"research_agent\" ||\n    value === \"writing_agent\" ||\n    value === \"critique_agent\"\n  );\n}\n",
  "src/app/features/subagents/subagent-renderer-config.ts": "/**\n * `subAgentRendererConfig`, used but not shown by\n * https://docs.copilotkit.ai/angular/ms-agent-harness-dotnet/multi-agent/subagents\n *\n * Unchanged from the Angular Showcase's\n * features/agent-state/subagent-renderer-config.ts.\n */\nimport type { RenderToolCallConfig } from \"@copilotkit/angular\";\nimport { z } from \"zod\";\n\nimport { SubAgentActivityCard } from \"./subagent-cards\";\nimport type { SubAgentName } from \"./subagent-model\";\n\n/**\n * Build a route-lifetime subagent renderer that also matches runtimes whose\n * assistant messages do not carry an agent identifier.\n */\nexport function subAgentRendererConfig(\n  name: SubAgentName,\n): RenderToolCallConfig<{ task: string }> {\n  return {\n    name,\n    args: z.object({ task: z.string() }),\n    component: SubAgentActivityCard as unknown as RenderToolCallConfig<{\n      task: string;\n    }>[\"component\"],\n  };\n}\n",
  "src/app/features/subagents/subagents-chat.component.ts": "/**\n * \"Rendering a live delegation log\", from\n * https://docs.copilotkit.ai/angular/ms-agent-harness-dotnet/multi-agent/subagents\n *\n * The class members between the region markers are the guide's snippet,\n * unchanged. The two fields it reads but does not show are resolved the way\n * the Angular Showcase's agent-state-feature.component.ts resolves them for\n * this demo: `feature` is \"subagents\", and `agentId` is the runtime key the\n * supervisor is registered under in server.ts. Template and layout come from\n * that same showcase component, with its showcase chat host replaced by a\n * plain copilot-chat on the same agent.\n */\nimport { Component, computed } from \"@angular/core\";\nimport {\n  CopilotChat,\n  injectAgentStore,\n  registerRenderToolCall,\n} from \"@copilotkit/angular\";\n\nimport { DelegationLogComponent } from \"./subagent-cards\";\nimport type { SubAgentName } from \"./subagent-model\";\nimport { readDelegations } from \"./subagent-model\";\nimport { subAgentRendererConfig } from \"./subagent-renderer-config\";\n\n@Component({\n  selector: \"app-subagents-chat\",\n  imports: [CopilotChat, DelegationLogComponent],\n  template: `\n    <main class=\"agent-state-page subagents\">\n      <aside aria-label=\"Live supervisor delegation state\">\n        <showcase-delegation-log [delegations]=\"delegations()\" />\n      </aside>\n      <section class=\"chat-surface\" aria-label=\"CopilotKit assistant\">\n        <copilot-chat [agentId]=\"agentId\" />\n      </section>\n    </main>\n  `,\n  styles: `\n    :host {\n      display: block;\n      height: 100%;\n    }\n    .agent-state-page {\n      height: 100%;\n      min-height: 0;\n      background: #eef3f7;\n    }\n    .chat-surface {\n      min-width: 0;\n      height: 100%;\n      background: #fff;\n    }\n    .subagents {\n      display: grid;\n      grid-template-columns: minmax(18rem, 0.85fr) minmax(0, 1.35fr);\n      gap: 1rem;\n      padding: 1rem;\n    }\n    .subagents aside {\n      min-width: 0;\n      overflow: auto;\n    }\n    .subagents .chat-surface {\n      overflow: hidden;\n      border: 1px solid #d8e0ea;\n      border-radius: 1rem;\n    }\n    @media (max-width: 52rem) {\n      .subagents {\n        grid-template-columns: 1fr;\n        grid-template-rows: auto minmax(30rem, 55vh);\n        overflow: auto;\n      }\n    }\n  `,\n})\nexport class SubagentsChatComponent {\n  protected readonly feature = \"subagents\";\n  protected readonly agentId = \"subagents\";\n  // subagents : rendering a live delegation log start\n  private readonly agentStore = injectAgentStore(this.agentId);\n  protected readonly delegations = computed(() =>\n    readDelegations(this.agentStore().state()),\n  );\n\n  constructor() {\n    if (this.feature === \"subagents\") {\n      this.registerSubAgent(\"research_agent\");\n      this.registerSubAgent(\"writing_agent\");\n      this.registerSubAgent(\"critique_agent\");\n    }\n  }\n\n  private registerSubAgent(name: SubAgentName): void {\n    registerRenderToolCall(subAgentRendererConfig(name));\n  }\n  // subagents : rendering a live delegation log end\n}\n",
  "src/app/features/threads/conversations.component.ts": "// threads : threads drawer and chat start\n/**\n * The drawer-plus-chat sample, verbatim. Both sit under one\n * `provideCopilotChatConfiguration`, which is what makes selection and\n * new-thread actions in the drawer update the chat.\n * https://docs.copilotkit.ai/angular/ms-agent-harness-dotnet/guides/threads-memory-attachments-headless\n */\n\nimport { Component } from '@angular/core';\nimport {\n  CopilotChat,\n  CopilotThreadsDrawer,\n  provideCopilotChatConfiguration,\n} from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-conversations',\n  imports: [CopilotChat, CopilotThreadsDrawer],\n  providers: [provideCopilotChatConfiguration({ agentId: 'support' })],\n  template: `\n    <copilot-threads-drawer agentId=\"support\" [limit]=\"20\" />\n    <copilot-chat />\n  `,\n})\nexport class ConversationsComponent {}\n// threads : threads drawer and chat end\n",
  "src/app/features/threads/thread-list.component.ts": "// threads : custom thread list start\n/**\n * \"For a custom thread list, use injectThreads\", verbatim.\n * https://docs.copilotkit.ai/angular/ms-agent-harness-dotnet/guides/threads-memory-attachments-headless\n */\n\nimport { Component } from '@angular/core';\nimport { injectThreads } from '@copilotkit/angular';\n\n@Component({\n  selector: 'app-thread-list',\n  template: `\n    <button type=\"button\" (click)=\"threads.startNewThread()\">\n      New conversation\n    </button>\n\n    @if (threads.isLoading()) {\n      <p>Loading conversations…</p>\n    } @else {\n      @for (thread of threads.threads(); track thread.id) {\n        <button type=\"button\" (click)=\"select(thread.id)\">\n          {{ thread.name ?? \"Untitled conversation\" }}\n        </button>\n      }\n    }\n\n    @if (threads.listError()) {\n      <button type=\"button\" (click)=\"threads.refetchThreads()\">Retry</button>\n    }\n  `,\n})\nexport class ThreadListComponent {\n  // threads : inject threads start\n  readonly threads = injectThreads({\n    agentId: 'support',\n    limit: 20,\n  });\n  // threads : inject threads end\n\n  protected select(threadId: string): void {\n    // Store this id and bind it to CopilotChat's threadId input.\n    console.log(threadId);\n  }\n}\n// threads : custom thread list end\n",
  "src/app/features/threads/threads-demo.component.ts": "/**\n * Harness wrapper mounting both thread surfaces from the guide: the hand-built\n * list on `injectThreads`, and the drop-in drawer beside a chat.\n *\n * Layout only. Both surfaces are published components used exactly as the guide\n * shows them — `thread-list.component.ts` and `conversations.component.ts` are\n * untouched, and nothing here changes their markup or behaviour. The two panes\n * sit side by side inside the viewport so the list and the chat are visible at\n * once; stacked, the chat fell below the fold and the demo had to be scrolled\n * in two directions to be read.\n *\n * The `::ng-deep` rules reach into `app-conversations` to give the drawer and\n * the chat a height to fill. They live here, in harness code, rather than in\n * the verbatim snippet component.\n */\nimport { Component } from '@angular/core';\n\nimport { ConversationsComponent } from './conversations.component';\nimport { ThreadListComponent } from './thread-list.component';\n\n@Component({\n  selector: 'app-threads-demo',\n  imports: [ThreadListComponent, ConversationsComponent],\n  template: `\n    <div class=\"flex h-full min-h-0 flex-col gap-4 p-4 lg:flex-row\">\n      <section\n        class=\"flex min-h-0 flex-col overflow-hidden rounded-lg border border-slate-200 bg-white p-4 lg:w-72 lg:shrink-0\"\n      >\n        <h2 class=\"mb-2 shrink-0 text-sm font-semibold text-slate-900\">\n          Headless list — injectThreads\n        </h2>\n        <div class=\"min-h-0 flex-1 overflow-y-auto\">\n          <app-thread-list />\n        </div>\n      </section>\n\n      <section\n        class=\"flex min-h-0 flex-1 flex-col overflow-hidden rounded-lg border border-slate-200 bg-white p-4\"\n      >\n        <h2 class=\"mb-2 shrink-0 text-sm font-semibold text-slate-900\">\n          CopilotThreadsDrawer + chat\n        </h2>\n        <div class=\"min-h-0 flex-1\">\n          <app-conversations />\n        </div>\n      </section>\n    </div>\n  `,\n  styles: [\n    `\n      :host {\n        display: block;\n        height: 100%;\n        min-height: 0;\n      }\n\n      app-conversations {\n        display: flex;\n        gap: 1rem;\n        height: 100%;\n        min-height: 0;\n      }\n\n      /* The drawer keeps its own width; the chat takes the rest. */\n      ::ng-deep app-conversations > copilot-threads-drawer {\n        flex: 0 0 auto;\n        min-height: 0;\n        overflow-y: auto;\n      }\n\n      ::ng-deep app-conversations > copilot-chat {\n        display: flex;\n        flex: 1 1 auto;\n        flex-direction: column;\n        min-width: 0;\n        min-height: 0;\n      }\n    `,\n  ],\n})\nexport class ThreadsDemoComponent {}\n",
  "src/app/features/tools/incident-card.component.ts": "// frontend tools : let the agent display one of your components start\n/**\n * \"Let the agent display one of your components\", verbatim.\n * https://docs.copilotkit.ai/angular/ms-agent-harness-dotnet/guides/frontend-tools-generative-ui\n */\n\nimport { Component, input } from \"@angular/core\";\nimport { AngularToolCall, ToolRenderer } from \"@copilotkit/angular\";\n\ntype IncidentArgs = { id: string; severity: string };\n\n@Component({\n  selector: \"app-incident-card\",\n  standalone: true,\n  template: `\n    @let call = toolCall();\n    @if (call.status === \"in-progress\") {\n      <p>Loading incident…</p>\n    } @else {\n      <article>\n        <strong>{{ call.args.id }}</strong>\n        <span>{{ call.args.severity }}</span>\n      </article>\n    }\n  `,\n})\nexport class IncidentCardComponent implements ToolRenderer<IncidentArgs> {\n  readonly toolCall = input.required<AngularToolCall<IncidentArgs>>();\n}\n// frontend tools : let the agent display one of your components end\n",
  "src/app/features/tools/tool-feature-model.ts": "// frontend tools : register a browser tool (change_background) start\n/**\n * The guide's `change_background` frontend tool.\n * https://docs.copilotkit.ai/angular/ms-agent-harness-dotnet/guides/frontend-tools-generative-ui\n *\n * `createBackgroundTool` is the guide's function, unchanged. Everything above\n * it is not in the guide: the snippet is quoted from the live Showcase without\n * its `BackgroundToolArgs` type, its `resolveGradient` helper, or its imports,\n * so those are defined here to make it runnable.\n */\n\nimport { type WritableSignal } from '@angular/core';\nimport { type FrontendToolConfig } from '@copilotkit/angular';\nimport { z } from 'zod';\n\n/** Arguments the agent may send to `change_background`. */\nexport type BackgroundToolArgs = {\n  background?: string;\n  color?: string;\n};\n\n/** Named presets so the agent can ask for a look without writing CSS. */\nconst GRADIENT_PRESETS: Record<string, string> = {\n  blue: 'linear-gradient(180deg, #0c4a6e 0%, #38bdf8 100%)',\n  violet: 'linear-gradient(180deg, #4c1d95 0%, #c084fc 100%)',\n  sunset: 'linear-gradient(180deg, #f97316 0%, #db2777 55%, #7c3aed 100%)',\n  forest: 'linear-gradient(180deg, #14532d 0%, #4ade80 100%)',\n  slate: 'linear-gradient(180deg, #0f172a 0%, #475569 100%)',\n};\n\nexport const DEFAULT_BACKGROUND = GRADIENT_PRESETS['slate'];\n\n/**\n * Accept a preset name, a bare CSS color, or a full gradient and always return\n * something safe to drop into a `background` style binding.\n */\nexport function resolveGradient(value: string | undefined): string {\n  const raw = value?.trim();\n  if (!raw) {\n    return DEFAULT_BACKGROUND;\n  }\n\n  const preset = GRADIENT_PRESETS[raw.toLowerCase()];\n  if (preset) {\n    return preset;\n  }\n\n  return raw.includes('gradient(')\n    ? raw\n    : `linear-gradient(180deg, ${raw} 0%, ${raw} 100%)`;\n}\n\n/** Create the frontend tool that applies a requested CSS gradient. */\nexport function createBackgroundTool(\n  background: WritableSignal<string>,\n): FrontendToolConfig<BackgroundToolArgs> {\n  return {\n    name: 'change_background',\n    description: 'Change the application background to a CSS gradient.',\n    parameters: z.object({\n      background: z.string().optional(),\n      color: z.string().optional(),\n    }),\n    handler: async (args) => {\n      const next = resolveGradient(args.background ?? args.color);\n      background.set(next);\n      return { background: next };\n    },\n  };\n}\n// frontend tools : register a browser tool (change_background) end\n",
  "src/app/features/tools/tools-chat.component.ts": "// frontend tools : register tools and renderers start\n/**\n * Mounts the two mountable halves of the guide's frontend-tools section against\n * one chat, and records the third path, which cannot be mounted at all.\n *\n * `registerRenderToolCall` — the tool runs on the server (the Agent Framework\n * agent's weather tool) and the browser only renders its call, through\n * WeatherCardComponent.\n *\n * `registerFrontendTool` — the tool runs in the browser. `change_background`\n * has a handler and no component, so it renders nothing in chat; its result is\n * the page itself changing. The registration is removed when this injector is\n * destroyed.\n *\n * `registerComponent` — the guide's new first section: a component the agent\n * displays, with no handler and nothing on the agent side. `show_incident` is\n * declared here by the frontend and forwarded to the agent over AG-UI, so the\n * Agent Framework process never learns about it. Needs @copilotkit/angular\n * 0.5.0 or newer; this repo runs 0.5.2.\n *\n * The guide's other `registerFrontendTool` sample is a second `getWeather`\n * that runs in the browser. It is not mounted: it would collide with the\n * server-side tool of the same name, and it calls an `/api/weather` endpoint\n * this repo does not serve.\n *\n * https://docs.copilotkit.ai/angular/ms-agent-harness-dotnet/guides/frontend-tools-generative-ui\n */\n\nimport { Component, signal } from '@angular/core';\nimport {\n  CopilotSidebar,\n  registerComponent,\n  registerFrontendTool,\n  registerRenderToolCall,\n} from '@copilotkit/angular';\nimport { z } from 'zod';\n\nimport { IncidentCardComponent } from './incident-card.component';\nimport {\n  DEFAULT_BACKGROUND,\n  createBackgroundTool,\n} from './tool-feature-model';\nimport { WeatherCardComponent } from './weather-card.component';\n\n@Component({\n  selector: 'app-tools-chat',\n  imports: [CopilotSidebar],\n  template: `\n    <div\n      style=\"height: 100%; display: flex; flex-direction: column; gap: 0.75rem; padding: 0.75rem; transition: background 400ms ease\"\n      [style.background]=\"background()\"\n    >\n        <copilot-sidebar />\n\n    </div>\n  `,\n})\nexport class ToolsChatComponent {\n  /** Written by the agent through the change_background handler. */\n  protected readonly background = signal(DEFAULT_BACKGROUND);\n\n  constructor() {\n    // frontend tools : render a tool result start\n    registerRenderToolCall({\n      name: 'getWeather',\n      args: z.object({ city: z.string() }),\n      component: WeatherCardComponent,\n    });\n    // frontend tools : render a tool result end\n\n    // frontend tools : register a browser tool start\n    registerFrontendTool(createBackgroundTool(this.background));\n    // frontend tools : register a browser tool end\n\n    // frontend tools : let the agent display one of your components start\n    registerComponent({\n      name: \"show_incident\",\n      description: \"Show one incident from the incident table.\",\n      parameters: z.object({\n        id: z.string().describe(\"The incident id, such as INC-4711\"),\n        severity: z.string().describe(\"One of sev1, sev2, sev3\"),\n      }),\n      component: IncidentCardComponent,\n    });\n    // frontend tools : let the agent display one of your components end\n  }\n}\n// frontend tools : register tools and renderers end\n",
  "src/app/features/tools/weather-card.component.ts": "// frontend tools : render a tool result start\n/**\n * \"Render a tool result\", verbatim.\n * https://docs.copilotkit.ai/angular/ms-agent-harness-dotnet/guides/frontend-tools-generative-ui\n */\n\nimport { Component, input } from '@angular/core';\nimport { type AngularToolCall, type ToolRenderer } from '@copilotkit/angular';\n\ntype WeatherArgs = { city: string };\n\n@Component({\n  selector: 'app-weather-card',\n  template: `\n    @let call = toolCall();\n    @if (call.status === \"complete\") {\n      <article>\n        <strong>{{ call.args.city }}</strong>\n        <p>{{ call.result }}</p>\n      </article>\n    } @else {\n      <p>Loading weather for {{ call.args.city ?? \"…\" }}</p>\n    }\n    <p>Tool Call done </p>\n  `,\n})\nexport class WeatherCardComponent implements ToolRenderer<WeatherArgs> {\n  readonly toolCall = input.required<AngularToolCall<WeatherArgs>>();\n}\n// frontend tools : render a tool result end\n",
  "src/app/features/webmcp/order-search.component.ts": "// webmcp : angular frontend tool start\n/**\n * \"Angular frontend tool\", verbatim from\n * https://docs.copilotkit.ai/angular/ms-agent-harness-dotnet/webmcp\n *\n * The only addition is the `searchOrders` import: the guide calls it without\n * defining it, so ./search-orders.ts is self-defined.\n */\nimport { Component } from \"@angular/core\";\nimport { registerFrontendTool } from \"@copilotkit/angular\";\nimport { z } from \"zod\";\n\nimport { searchOrders } from \"./search-orders\";\n\n@Component({\n  selector: \"app-order-search\",\n  standalone: true,\n  template: \"\",\n})\nexport class OrderSearchComponent {\n  constructor() {\n    registerFrontendTool({\n      name: \"searchOrders\",\n      description: \"Search the signed-in user's orders by status\",\n      parameters: z.object({\n        status: z.enum([\"open\", \"shipped\", \"delivered\"]),\n      }),\n      handler: async ({ status }) => {\n        const orders = await searchOrders(status);\n        return JSON.stringify(orders);\n      },\n      webmcp: {\n        annotations: {\n          readOnlyHint: true,\n        },\n      },\n    });\n  }\n}\n// webmcp : angular frontend tool end\n",
  "src/app/features/webmcp/search-orders.ts": "/**\n * SELF-DEFINED — not from the docs.\n *\n * https://docs.copilotkit.ai/angular/ms-agent-harness-dotnet/webmcp calls\n * `searchOrders(status)` in both of its examples but never defines it. This is\n * a stand-in with fixed in-memory orders so the handler has something real to\n * return. A real app would call its own orders API here, and enforce\n * authentication and authorization there — WebMCP annotations are hints, not\n * security controls.\n */\nexport type OrderStatus = \"open\" | \"shipped\" | \"delivered\";\n\nexport interface Order {\n  id: string;\n  item: string;\n  status: OrderStatus;\n}\n\nconst ORDERS: readonly Order[] = [\n  { id: \"ord-1001\", item: \"Mechanical keyboard\", status: \"open\" },\n  { id: \"ord-1002\", item: \"USB-C dock\", status: \"shipped\" },\n  { id: \"ord-1003\", item: \"27-inch monitor\", status: \"delivered\" },\n  { id: \"ord-1004\", item: \"Desk lamp\", status: \"open\" },\n];\n\nexport async function searchOrders(status: OrderStatus): Promise<Order[]> {\n  return ORDERS.filter((order) => order.status === status);\n}\n",
  "src/app/features/webmcp/webmcp-chat.component.ts": "/**\n * Mounts the guide's Angular frontend tool beside a chat, so the same\n * `searchOrders` handler can be called two ways: by the CopilotKit agent\n * through the chat, and by a WebMCP-aware browser agent through\n * `document.modelContext`. The panel only reports whether the page has\n * `document.modelContext` at all — without it CopilotKit registers nothing,\n * by design.\n * https://docs.copilotkit.ai/angular/ms-agent-harness-dotnet/webmcp\n */\nimport { Component, afterNextRender, signal } from '@angular/core';\nimport { CopilotChat } from '@copilotkit/angular';\n\nimport { OrderSearchComponent } from './order-search.component';\n\n@Component({\n  selector: 'app-webmcp-chat',\n  imports: [CopilotChat, OrderSearchComponent],\n  template: `\n    <app-order-search />\n    <div style=\"display: flex; height: 100%; gap: 1rem\">\n      <div style=\"width: 20rem; overflow-y: auto; padding: 1rem\">\n        <p>\n          <code>document.modelContext</code>:\n          <strong>{{ available() ? 'available' : 'not available' }}</strong>\n        </p>\n      </div>\n      <div style=\"flex: 1; min-width: 0\">\n        <copilot-chat />\n      </div>\n    </div>\n  `,\n})\nexport class WebmcpChatComponent {\n  protected readonly available = signal(false);\n\n  constructor() {\n    afterNextRender(() =>\n      this.available.set('modelContext' in document),\n    );\n  }\n}\n",
  "src/app/features/webmcp/webmcp-core-demo.component.ts": "/**\n * Runs the guide's \"WebMCP only, with no agent\" module. Importing ./webmcp\n * creates its CopilotKitCore; no chat, Runtime or agent is involved. The panel\n * lists the tool names that core keeps registered on `document.modelContext`.\n * https://docs.copilotkit.ai/angular/ms-agent-harness-dotnet/webmcp\n */\nimport { Component, afterNextRender, signal } from '@angular/core';\n\n@Component({\n  selector: 'app-webmcp-core-demo',\n  template: `\n    <div style=\"padding: 1rem\">\n      <p>\n        <code>document.modelContext</code>:\n        <strong>{{ available() ? 'available' : 'not available' }}</strong>\n      </p>\n      <p>\n        CopilotKitCore created with tools:\n        <code>{{ tools().join(', ') || '—' }}</code>\n      </p>\n    </div>\n  `,\n})\nexport class WebmcpCoreDemoComponent {\n  protected readonly available = signal(false);\n  protected readonly tools = signal<string[]>([]);\n\n  constructor() {\n    afterNextRender(async () => {\n      this.available.set('modelContext' in document);\n      const { copilotkit } = await import('./webmcp');\n      this.tools.set(copilotkit.tools.map((tool) => tool.name));\n    });\n  }\n}\n",
  "src/app/features/webmcp/webmcp.ts": "// webmcp : webmcp only with no agent start\n/**\n * \"WebMCP only, with no agent\", verbatim from\n * https://docs.copilotkit.ai/angular/ms-agent-harness-dotnet/webmcp\n *\n * Registers the tool straight on a CopilotKitCore, with no Runtime and no\n * agent. The instance is created when this module is first imported (the\n * /webmcp/core-demo route) and kept alive for the rest of the page's life, as\n * the guide asks. The only addition is the self-defined `searchOrders` import.\n */\nimport { CopilotKitCore } from \"@copilotkit/core\";\nimport { z } from \"zod\";\n\nimport { searchOrders } from \"./search-orders\";\n\nexport const copilotkit = new CopilotKitCore({\n  tools: [\n    {\n      name: \"searchOrders\",\n      description: \"Search the signed-in user's orders by status\",\n      parameters: z.object({\n        status: z.enum([\"open\", \"shipped\", \"delivered\"]),\n      }),\n      handler: async ({ status }) => {\n        const orders = await searchOrders(status);\n        return JSON.stringify(orders);\n      },\n      webmcp: {\n        annotations: {\n          readOnlyHint: true,\n        },\n      },\n    },\n  ],\n});\n// webmcp : webmcp only with no agent end\n",
  "../backend/Program.cs": "// SELF-DEFINED — the agent backend this harness's Copilot Runtime points at.\n//\n// https://docs.copilotkit.ai/angular/ms-agent-harness-dotnet/quickstart ships no\n// backend for this framework (\"setup skipped: agent-setup is not bundled for\n// ms-agent-harness-dotnet\") and sends you to the runtime guide, which is\n// TypeScript only. So this file is the smallest Microsoft Agent Harness host\n// that answers the runtime's HttpAgents, built from the same pieces as the\n// CopilotKit showcase's\n// showcase/integrations/ms-agent-harness-dotnet/agent/Program.cs (`AddAGUI`,\n// `MapAGUI`, one shared `OpenAIClient` handed to each factory,\n// `chatClient.AsHarnessAgent(...)`, the same package pins), minus the\n// showcase's own test plumbing (ApiKeyResolver, aimock header forwarding,\n// CVDIAG diagnostics) — see CLAUDE.md, \"Showcase-only code\".\n//\n// Endpoints (each one an AG-UI agent streaming over SSE):\n//   POST /           the `default` (and `support`) agent\n//   POST /subagents  the Sub-Agents supervisor, SubagentsAgent.cs, from the\n//                    showcase unchanged\n//   POST /research   the AG-UI guide's `research-agent` (ResearchAgent.cs,\n//                    self-defined)\n//   GET  /health     liveness, for the frontend's backend-health check\n//\n// Mirrors ../ms-agent-py/backend/main.py, the Python harness's equivalent.\n// quickstart : connect the selected agent backend\nusing System.ClientModel;\nusing System.ComponentModel;\nusing Microsoft.Agents.AI;\nusing Microsoft.Agents.AI.Hosting.AGUI.AspNetCore;\nusing Microsoft.AspNetCore.Http.Json;\nusing Microsoft.Extensions.AI;\nusing Microsoft.Extensions.Options;\nusing OpenAI;\n\nLoadDotEnv(Path.Combine(AppContext.BaseDirectory, \".env\"));\nLoadDotEnv(Path.Combine(Directory.GetCurrentDirectory(), \".env\"));\n\nvar builder = WebApplication.CreateBuilder(args);\nvar port = Environment.GetEnvironmentVariable(\"PORT\") ?? \"8251\";\nbuilder.WebHost.UseUrls($\"http://0.0.0.0:{port}\");\n\nbuilder.Services.AddAGUI();\n// The browser calls GET /health directly (components/backend-health.ts), so\n// this origin must be reachable cross-origin. Same policy as main.py's\n// CORSMiddleware.\nbuilder.Services.AddCors(options =>\n    options.AddDefaultPolicy(policy => policy.AllowAnyOrigin().AllowAnyMethod().AllowAnyHeader()));\n\nvar app = builder.Build();\napp.UseCors();\n\nvar loggerFactory = app.Services.GetRequiredService<ILoggerFactory>();\nvar logger = loggerFactory.CreateLogger(\"Program\");\nvar jsonOptions = app.Services.GetRequiredService<IOptions<JsonOptions>>().Value.SerializerOptions;\n\n// As in the showcase's Program.cs, this one OpenAIClient is threaded into\n// every agent, the sub-agents factory included. OPENAI_API_KEY is required;\n// OPENAI_BASE_URL is optional (the OpenAI SDK's default endpoint otherwise).\n// The showcase's ApiKeyResolver is left out — see CLAUDE.md, \"Showcase-only code\".\nvar apiKey = builder.Configuration[\"OPENAI_API_KEY\"]\n    ?? throw new InvalidOperationException(\"OPENAI_API_KEY is not set.\");\nvar endpoint = builder.Configuration[\"OPENAI_BASE_URL\"];\nvar model = Environment.GetEnvironmentVariable(\"OPENAI_CHAT_MODEL_ID\") ?? \"gpt-5.4-mini\";\nlogger.LogInformation(\"OpenAI endpoint {Endpoint}, default-agent model {Model}\",\n    string.IsNullOrWhiteSpace(endpoint) ? \"(OpenAI default)\" : endpoint, model);\n\nvar openAiClient = string.IsNullOrWhiteSpace(endpoint)\n    ? new OpenAIClient(new ApiKeyCredential(apiKey))\n    : new OpenAIClient(new ApiKeyCredential(apiKey), new OpenAIClientOptions { Endpoint = new Uri(endpoint) });\n\n// frontend tools : server tool getWeather start\n[Description(\"Get the weather for a location.\")]\nstatic string GetWeather([Description(\"The location to get weather for\")] string location)\n{\n    var normalized = string.IsNullOrWhiteSpace(location) ? \"the requested location\" : location.Trim();\n    return $\"The weather for {normalized} is 70 degrees.\";\n}\n// frontend tools : server tool getWeather end\n\n// quickstart : default agent start\nAIAgent defaultAgent = openAiClient.GetChatClient(model).AsIChatClient().AsHarnessAgent(\n    128_000,\n    8_192,\n    new HarnessAgentOptions\n    {\n        Name = \"sample_agent\",\n        ChatOptions = new ChatOptions\n        {\n            Instructions = \"You are a helpful assistant.\",\n            MaxOutputTokens = 8_192,\n            Tools = [AIFunctionFactory.Create(GetWeather, options: new() { Name = \"getWeather\", SerializerOptions = jsonOptions })],\n        },\n    });\n// quickstart : default agent end\n\n// subagents : supervisor agent start\nvar subagentsFactory = new SubagentsAgentFactory(openAiClient, loggerFactory, jsonOptions);\n// subagents : supervisor agent end\n// ag-ui : research agent start\nvar researchAgent = ResearchAgent.Create(openAiClient.GetChatClient(model).AsIChatClient());\n// ag-ui : research agent end\n\n// quickstart : expose agent framework endpoint start\napp.MapAGUI(\"/\", defaultAgent);\n// quickstart : expose agent framework endpoint end\n// subagents : expose supervisor endpoint start\napp.MapAGUI(\"/subagents\", subagentsFactory.CreateAgent());\n// subagents : expose supervisor endpoint end\n// ag-ui : expose research agent endpoint start\napp.MapAGUI(\"/research\", researchAgent);\n// ag-ui : expose research agent endpoint end\n\napp.MapGet(\"/health\", () => Results.Ok(new { status = \"ok\" }));\n\nawait app.RunAsync();\n\n// .NET has no load_dotenv; read KEY=VALUE lines from backend/.env without\n// overriding variables already set in the environment.\nstatic void LoadDotEnv(string path)\n{\n    if (!File.Exists(path)) return;\n    foreach (var raw in File.ReadAllLines(path))\n    {\n        var line = raw.Trim();\n        if (line.Length == 0 || line.StartsWith('#')) continue;\n        var eq = line.IndexOf('=');\n        if (eq <= 0) continue;\n        var key = line[..eq].Trim();\n        var value = line[(eq + 1)..].Trim().Trim('\"');\n        if (Environment.GetEnvironmentVariable(key) is null)\n        {\n            Environment.SetEnvironmentVariable(key, value);\n        }\n    }\n}\n",
  "../backend/SubagentsAgent.cs": "// @region[supervisor-delegation-tools]\n// @region[subagent-setup]\nusing System.ComponentModel;\nusing System.Diagnostics.CodeAnalysis;\nusing System.Net.Http;\nusing System.Runtime.CompilerServices;\nusing System.Text.Json;\nusing System.Text.Json.Serialization;\nusing Microsoft.Agents.AI;\nusing Microsoft.Extensions.AI;\nusing Microsoft.Extensions.Logging;\nusing Microsoft.Extensions.Logging.Abstractions;\nusing OpenAI;\nusing System.ClientModel;\n\n// SubagentsAgent — backs the /subagents demo.\n//\n// Mirrors langgraph-python/src/agents/subagents.py and\n// google-adk/src/agents/subagents_agent.py:\n//\n//   * A supervisor ChatClientAgent exposes three tools — `research_agent`,\n//     `writing_agent`, `critique_agent` — each of which delegates to a\n//     specialised sub-agent.\n//\n//   * Each sub-agent is implemented as a single-shot secondary chat-client\n//     call with its own system prompt. This is conceptually identical to\n//     spawning a separate ChatClientAgent + Runner per delegation; we use a\n//     single-shot call here to keep the demo wiring tight (and to mirror the\n//     google-adk reference, which does the same with `genai.Client`).\n//\n//   * Every delegation is recorded in `state.delegations` — a list of\n//     `Delegation { id, sub_agent, task, status, result }` records — and\n//     emitted to the UI as a state-snapshot DataContent payload after the\n//     supervisor's stream completes. (The snapshot also gets re-emitted on\n//     each tool call so the UI's `running` -> `completed` transition is\n//     visible mid-stream; see `EmitSnapshotAsync` below.)\n[SuppressMessage(\"Performance\", \"CA1812:Avoid uninstantiated internal classes\", Justification = \"Instantiated by SubagentsAgentFactory\")]\ninternal sealed class SubagentsAgent : DelegatingAIAgent\n{\n    private readonly ILogger<SubagentsAgent> _logger;\n    private readonly SubagentsStore _store;\n\n    public SubagentsAgent(\n        AIAgent innerAgent,\n        SubagentsStore store,\n        ILogger<SubagentsAgent>? logger = null)\n        : base(innerAgent)\n    {\n        ArgumentNullException.ThrowIfNull(innerAgent);\n        ArgumentNullException.ThrowIfNull(store);\n        _store = store;\n        _logger = logger ?? NullLogger<SubagentsAgent>.Instance;\n    }\n\n    protected override Task<AgentResponse> RunCoreAsync(IEnumerable<ChatMessage> messages, AgentSession? thread = null, AgentRunOptions? options = null, CancellationToken cancellationToken = default)\n    {\n        return RunCoreStreamingAsync(messages, thread, options, cancellationToken).ToAgentResponseAsync(cancellationToken);\n    }\n\n    protected override async IAsyncEnumerable<AgentResponseUpdate> RunCoreStreamingAsync(\n        IEnumerable<ChatMessage> messages,\n        AgentSession? thread = null,\n        AgentRunOptions? options = null,\n        [EnumeratorCancellation] CancellationToken cancellationToken = default)\n    {\n        ArgumentNullException.ThrowIfNull(messages);\n        var messageList = messages as IReadOnlyList<ChatMessage> ?? messages.ToList();\n\n        // Bind the tool's read/write target to the current thread so each\n        // conversation appends to its own delegation list. The store\n        // exposes a per-thread \"active\" handle that the static tool\n        // function reads. We restore the previous value on exit so nested /\n        // overlapping runs don't trample each other.\n        var previous = (AgentSession?)_store.SetActiveThread(thread);\n        try\n        {\n            await foreach (var update in InnerAgent.RunStreamingAsync(messageList, thread, options, cancellationToken).ConfigureAwait(false))\n            {\n                yield return update;\n\n                // Flush any state changes the tool made during this update\n                // chunk. The inner ChatClientAgent doesn't emit DataContent\n                // for tool calls, so the UI would otherwise only see the\n                // final post-stream snapshot — losing the visible\n                // running -> completed transition that makes the demo\n                // compelling. We dedupe via SubagentsStore.TakeDirtyVersion\n                // so we don't spam identical snapshots across token chunks.\n                if (_store.TakeDirty(thread))\n                {\n                    var snapshot = _store.BuildSnapshot(thread);\n                    var bytes = JsonSerializer.SerializeToUtf8Bytes(\n                        snapshot,\n                        SubagentsSerializerContext.Default.SubagentsSnapshot);\n                    yield return new AgentResponseUpdate\n                    {\n                        Contents = [new DataContent(bytes, \"application/json\")],\n                    };\n                }\n            }\n        }\n        finally\n        {\n            _store.SetActiveThread(previous);\n        }\n\n        // Final snapshot — guarantees at least one state event per turn\n        // even if the supervisor produced no tool calls (so the UI sees a\n        // stable empty `delegations` list rather than `undefined`).\n        var finalSnapshot = _store.BuildSnapshot(thread);\n        var finalBytes = JsonSerializer.SerializeToUtf8Bytes(\n            finalSnapshot,\n            SubagentsSerializerContext.Default.SubagentsSnapshot);\n        yield return new AgentResponseUpdate\n        {\n            Contents = [new DataContent(finalBytes, \"application/json\")],\n        };\n    }\n}\n\n/// <summary>\n/// Per-thread store of delegation entries. Reads/writes are synchronized via\n/// a single lock — the demo workload is light and the lock is held only\n/// across the read-modify-write of an in-memory list.\n/// </summary>\ninternal sealed class SubagentsStore\n{\n    // Instance-scoped (not static) so multiple SubagentsStore instances —\n    // e.g. test helpers, future multi-tenant wiring — don't share global\n    // state with their per-instance `_slots` dict.\n    private readonly object _globalSlot = new();\n    private readonly AsyncLocal<object?> _activeThreadKey = new();\n\n    private readonly Dictionary<object, ThreadSlot> _slots = new();\n    private readonly object _lock = new();\n\n    public object? SetActiveThread(AgentSession? thread)\n    {\n        var prior = _activeThreadKey.Value;\n        _activeThreadKey.Value = thread ?? _globalSlot;\n        return prior;\n    }\n\n    public string AppendRunning(string subAgent, string task)\n    {\n        var entry = new SubagentDelegation(\n            Id: Guid.NewGuid().ToString(\"n\")[..16],\n            SubAgent: subAgent,\n            Task: task,\n            Status: \"running\",\n            Result: \"\");\n        lock (_lock)\n        {\n            // Mirror into every live conversation slot when the active key\n            // collapses to global — harness tool invocation can drop the\n            // AsyncLocal set by SetActiveThread (same root cause as\n            // D5ParityAgents SnapshotStore). Without this the left-panel UI\n            // stays empty while chat tool cards still stream.\n            foreach (var slot in WriteTargets())\n            {\n                slot.Delegations.Add(entry);\n                slot.DirtyVersion++;\n            }\n        }\n        return entry.Id;\n    }\n\n    public void Update(string id, string status, string result)\n    {\n        lock (_lock)\n        {\n            foreach (var slot in WriteTargets())\n            {\n                for (var i = 0; i < slot.Delegations.Count; i++)\n                {\n                    if (slot.Delegations[i].Id == id)\n                    {\n                        slot.Delegations[i] = slot.Delegations[i] with\n                        {\n                            Status = status,\n                            Result = result,\n                        };\n                        slot.DirtyVersion++;\n                        break;\n                    }\n                }\n            }\n        }\n    }\n\n    public bool TakeDirty(AgentSession? thread)\n    {\n        lock (_lock)\n        {\n            var slot = ResolveSlotForRead(thread);\n            if (slot is null)\n            {\n                return false;\n            }\n            if (slot.DirtyVersion == slot.LastEmittedVersion)\n            {\n                return false;\n            }\n            slot.LastEmittedVersion = slot.DirtyVersion;\n            return true;\n        }\n    }\n\n    public SubagentsSnapshot BuildSnapshot(AgentSession? thread)\n    {\n        lock (_lock)\n        {\n            var slot = ResolveSlotForRead(thread);\n            if (slot is null)\n            {\n                return new SubagentsSnapshot(Array.Empty<SubagentDelegation>());\n            }\n            // Defensive copy — caller may serialize after the lock releases.\n            return new SubagentsSnapshot(slot.Delegations.ToArray());\n        }\n    }\n\n    /// <summary>\n    /// Prefer the per-thread slot when it has delegations; otherwise fall\n    /// back to the global slot that tools land in when AsyncLocal doesn't\n    /// flow into the harness function-invocation context.\n    /// </summary>\n    private ThreadSlot? ResolveSlotForRead(AgentSession? thread)\n    {\n        if (thread is not null &&\n            _slots.TryGetValue(thread, out var threadSlot) &&\n            (threadSlot.Delegations.Count > 0 || threadSlot.DirtyVersion > 0))\n        {\n            return threadSlot;\n        }\n        if (_slots.TryGetValue(_globalSlot, out var globalSlot) &&\n            (globalSlot.Delegations.Count > 0 || globalSlot.DirtyVersion > 0))\n        {\n            return globalSlot;\n        }\n        if (thread is not null && _slots.TryGetValue(thread, out threadSlot))\n        {\n            return threadSlot;\n        }\n        return _slots.TryGetValue(_globalSlot, out globalSlot) ? globalSlot : null;\n    }\n\n    private IEnumerable<ThreadSlot> WriteTargets()\n    {\n        var key = _activeThreadKey.Value ?? _globalSlot;\n        yield return GetOrCreateSlot(key);\n\n        // When AsyncLocal missed and we wrote to global, also mirror into\n        // any already-bound conversation slots so the post-run snapshot\n        // (which keys by AgentSession) still sees the delegations.\n        if (ReferenceEquals(key, _globalSlot))\n        {\n            foreach (var kvp in _slots)\n            {\n                if (!ReferenceEquals(kvp.Key, _globalSlot))\n                {\n                    yield return kvp.Value;\n                }\n            }\n        }\n    }\n\n    private ThreadSlot GetOrCreateSlot(object key)\n    {\n        if (!_slots.TryGetValue(key, out var slot))\n        {\n            slot = new ThreadSlot();\n            _slots[key] = slot;\n        }\n        return slot;\n    }\n\n    private sealed class ThreadSlot\n    {\n        public List<SubagentDelegation> Delegations { get; } = new();\n        public long DirtyVersion { get; set; }\n        public long LastEmittedVersion { get; set; }\n    }\n}\n\ninternal sealed record SubagentDelegation(\n    [property: JsonPropertyName(\"id\")] string Id,\n    [property: JsonPropertyName(\"sub_agent\")] string SubAgent,\n    [property: JsonPropertyName(\"task\")] string Task,\n    [property: JsonPropertyName(\"status\")] string Status,\n    [property: JsonPropertyName(\"result\")] string Result);\n\ninternal sealed record SubagentsSnapshot(\n    [property: JsonPropertyName(\"delegations\")] IReadOnlyList<SubagentDelegation> Delegations);\n\n[JsonSerializable(typeof(SubagentsSnapshot))]\n[JsonSerializable(typeof(SubagentDelegation))]\n[JsonSerializable(typeof(IReadOnlyList<SubagentDelegation>))]\ninternal sealed partial class SubagentsSerializerContext : JsonSerializerContext;\n\n/// <summary>\n/// Factory that builds the supervisor agent + the three sub-agent tools.\n/// Mounted in Program.cs at `/subagents`.\n/// </summary>\npublic sealed class SubagentsAgentFactory\n{\n    private const int HarnessMaxContextWindowTokens = 128_000;\n    private const int HarnessMaxOutputTokens = 8_192;\n    private const string SubAgentModel = \"gpt-6-luna\";\n\n    // Each sub-agent is a single-shot ChatClient call (built per-delegation\n    // in DelegateAsync) with its own system prompt. They don't share memory\n    // or tools with the supervisor — the supervisor only sees their return\n    // value as a tool result.\n    private const string ResearchSystemPrompt =\n        \"You are a research sub-agent. Given a topic, produce a concise \" +\n        \"bulleted list of 3-5 key facts. No preamble, no closing.\";\n    private const string WritingSystemPrompt =\n        \"You are a writing sub-agent. Given a brief and optional source facts, \" +\n        \"produce a polished 1-paragraph draft. Be clear and concrete. No preamble.\";\n    private const string CritiqueSystemPrompt =\n        \"You are an editorial critique sub-agent. Given a draft, give 2-3 crisp, \" +\n        \"actionable critiques. No preamble.\";\n    // @endregion[subagent-setup]\n\n    private const string SupervisorPrompt =\n        \"You are a supervisor agent that coordinates three specialized \" +\n        \"sub-agents to produce high-quality deliverables.\\n\\n\" +\n        \"Available sub-agents (call them as tools):\\n\" +\n        \"  - research_agent: gathers facts on a topic.\\n\" +\n        \"  - writing_agent: turns facts + a brief into a polished draft.\\n\" +\n        \"  - critique_agent: reviews a draft and suggests improvements.\\n\\n\" +\n        \"For most non-trivial user requests, delegate in sequence: research -> \" +\n        \"write -> critique. Pass relevant facts/draft through the `task` argument \" +\n        \"of each tool. Each tool returns a JSON object shaped \" +\n        \"{status: 'completed' | 'failed', result?: string, error?: string}. \" +\n        \"If a sub-agent fails, surface the failure briefly to the user (don't \" +\n        \"fabricate a result) and decide whether to retry. Keep your own \" +\n        \"messages short — explain the plan once, delegate, then return a \" +\n        \"concise summary once done. The UI shows the user a live log of \" +\n        \"every sub-agent delegation, including the in-flight 'running' state.\";\n\n    private readonly OpenAIClient _openAiClient;\n    private readonly ILoggerFactory _loggerFactory;\n    private readonly ILogger _logger;\n    private readonly JsonSerializerOptions _jsonSerializerOptions;\n    private readonly SubagentsStore _store = new();\n\n    public SubagentsAgentFactory(\n        OpenAIClient openAiClient,\n        ILoggerFactory loggerFactory,\n        JsonSerializerOptions jsonSerializerOptions)\n    {\n        ArgumentNullException.ThrowIfNull(openAiClient);\n        ArgumentNullException.ThrowIfNull(loggerFactory);\n        ArgumentNullException.ThrowIfNull(jsonSerializerOptions);\n\n        _openAiClient = openAiClient;\n        _loggerFactory = loggerFactory;\n        _logger = loggerFactory.CreateLogger<SubagentsAgentFactory>();\n        _jsonSerializerOptions = jsonSerializerOptions;\n    }\n\n    public AIAgent CreateAgent()\n    {\n        var chatClient = _openAiClient.GetChatClient(\"gpt-6-luna\").AsLunaChatClient();\n\n        // Each sub-agent is exposed to the supervisor LLM as an AIFunction\n        // tool. When the supervisor invokes one, DelegateAsync runs a fresh\n        // ChatClient call with that sub-agent's system prompt, appends a\n        // Delegation entry to shared state, and returns the sub-agent's\n        // output to the supervisor as a tool result.\n        var research = AIFunctionFactory.Create(\n            (Func<string, CancellationToken, Task<string>>)((task, ct) =>\n                DelegateAsync(\"research_agent\", ResearchSystemPrompt, task, ct)),\n            options: new()\n            {\n                Name = \"research_agent\",\n                Description = \"Delegate a research task to the research sub-agent. Returns JSON {status, result?, error?}.\",\n                SerializerOptions = _jsonSerializerOptions,\n            });\n        var writing = AIFunctionFactory.Create(\n            (Func<string, CancellationToken, Task<string>>)((task, ct) =>\n                DelegateAsync(\"writing_agent\", WritingSystemPrompt, task, ct)),\n            options: new()\n            {\n                Name = \"writing_agent\",\n                Description = \"Delegate a drafting task to the writing sub-agent. Returns JSON {status, result?, error?}.\",\n                SerializerOptions = _jsonSerializerOptions,\n            });\n        var critique = AIFunctionFactory.Create(\n            (Func<string, CancellationToken, Task<string>>)((task, ct) =>\n                DelegateAsync(\"critique_agent\", CritiqueSystemPrompt, task, ct)),\n            options: new()\n            {\n                Name = \"critique_agent\",\n                Description = \"Delegate a critique task to the critique sub-agent. Returns JSON {status, result?, error?}.\",\n                SerializerOptions = _jsonSerializerOptions,\n            });\n        // @endregion[supervisor-delegation-tools]\n\n        var inner = chatClient.AsHarnessAgent(\n            HarnessMaxContextWindowTokens,\n            HarnessMaxOutputTokens,\n            new HarnessAgentOptions\n            {\n                Name = \"SubagentsSupervisor\",\n                Description = \"Sub-agents demo supervisor — coordinates research/writing/critique sub-agents.\",\n                ChatOptions = new ChatOptions\n                {\n                    Instructions = SupervisorPrompt,\n                    MaxOutputTokens = HarnessMaxOutputTokens,\n                    Tools = [research, writing, critique],\n                },\n            });\n\n        return new SubagentsAgent(inner, _store, _loggerFactory.CreateLogger<SubagentsAgent>());\n    }\n\n    /// <summary>\n    /// Common delegation flow — append a \"running\" entry, invoke a single-\n    /// shot secondary chat-client call, then update the entry to\n    /// \"completed\" / \"failed\". Returns a JSON string the supervisor LLM\n    /// reads as the tool result, mirroring the dict shape used by the\n    /// google-adk reference.\n    /// </summary>\n    private async Task<string> DelegateAsync(\n        string subAgent,\n        string systemPrompt,\n        string task,\n        CancellationToken cancellationToken)\n    {\n        ArgumentNullException.ThrowIfNull(task);\n        var entryId = _store.AppendRunning(subAgent, task);\n        _logger.LogInformation(\"subagent: starting {SubAgent} (entryId={EntryId}) task={TaskLength} chars\", subAgent, entryId, task.Length);\n\n        try\n        {\n            var secondary = _openAiClient.GetChatClient(SubAgentModel).AsLunaChatClient();\n            var messages = new List<ChatMessage>\n            {\n                new(ChatRole.System, systemPrompt),\n                new(ChatRole.User, task),\n            };\n            var response = await secondary.GetResponseAsync(messages, cancellationToken: cancellationToken).ConfigureAwait(false);\n            var text = response.Text?.Trim() ?? \"\";\n            if (string.IsNullOrEmpty(text))\n            {\n                _logger.LogWarning(\"subagent: {SubAgent} returned no text content\", subAgent);\n                _store.Update(entryId, \"failed\", \"sub-agent returned empty text\");\n                return JsonSerializer.Serialize(new { status = \"failed\", error = \"sub-agent returned empty text\" });\n            }\n\n            _store.Update(entryId, \"completed\", text);\n            return JsonSerializer.Serialize(new { status = \"completed\", result = text });\n        }\n        catch (HttpRequestException ex)\n        {\n            _logger.LogError(ex, \"subagent: {SubAgent} transport failure\", subAgent);\n            var msg = $\"sub-agent call failed: {ex.GetType().Name} (see server logs)\";\n            _store.Update(entryId, \"failed\", msg);\n            return JsonSerializer.Serialize(new { status = \"failed\", error = msg });\n        }\n        catch (ClientResultException ex)\n        {\n            _logger.LogError(ex, \"subagent: {SubAgent} upstream returned status {Status}\", subAgent, ex.Status);\n            var msg = $\"sub-agent call failed: upstream returned error status {ex.Status}\";\n            _store.Update(entryId, \"failed\", msg);\n            return JsonSerializer.Serialize(new { status = \"failed\", error = msg });\n        }\n        catch (OperationCanceledException)\n        {\n            _store.Update(entryId, \"failed\", \"sub-agent call cancelled\");\n            throw;\n        }\n    }\n}\n",
  "../backend/ResearchAgent.cs": "// SELF-DEFINED — not from the docs or the showcase.\n//\n// https://docs.copilotkit.ai/angular/ms-agent-harness-dotnet/ag-ui addresses an\n// agent as \"research-agent\" but never defines one. This is the smallest\n// harness agent that can answer to that runtime key, built the same way as the\n// default agent in Program.cs. Its instructions are the showcase's research\n// sub-agent prompt (`ResearchSystemPrompt` in SubagentsAgent.cs) — repeated\n// here because that constant is private — so its replies are recognisably\n// different from the default agent's.\n//\n// Mirrors ../ms-agent-py/backend/research_agent.py.\nusing Microsoft.Agents.AI;\nusing Microsoft.Extensions.AI;\n\ninternal static class ResearchAgent\n{\n    private const int HarnessMaxContextWindowTokens = 128_000;\n    private const int HarnessMaxOutputTokens = 8_192;\n\n    // Same text as SubagentsAgentFactory.ResearchSystemPrompt.\n    private const string ResearchInstructions =\n        \"You are a research sub-agent. Given a topic, produce a concise \" +\n        \"bulleted list of 3-5 key facts. No preamble, no closing.\";\n\n    public static AIAgent Create(IChatClient chatClient) =>\n        chatClient.AsHarnessAgent(\n            HarnessMaxContextWindowTokens,\n            HarnessMaxOutputTokens,\n            new HarnessAgentOptions\n            {\n                Name = \"research_agent\",\n                Description = \"Research agent: answers a topic with 3-5 key facts.\",\n                ChatOptions = new ChatOptions\n                {\n                    Instructions = ResearchInstructions,\n                    MaxOutputTokens = HarnessMaxOutputTokens,\n                    Tools = [],\n                },\n            });\n}\n",
  "../backend/Backend.csproj": "<!--\n  Project settings and package pins from the CopilotKit showcase,\n  showcase/integrations/ms-agent-harness-dotnet/agent/BeautifulChatAgent.csproj —\n  the project behind the file\n  https://docs.copilotkit.ai/angular/ms-agent-harness-dotnet/multi-agent/subagents\n  quotes. Those pins are what make the guide's C# (AgentSession,\n  AgentResponse, RunCoreAsync/RunCoreStreamingAsync overrides, AsHarnessAgent)\n  compile.\n\n  Differences from the showcase project:\n  - Only the files this harness uses are compiled.\n  - The showcase's ..\\_shared\\dotnet\\LunaChatClientExtensions.cs lives in\n    shared/ here, unchanged.\n  - No UserSecretsId (configuration comes from backend/.env).\n-->\n<Project Sdk=\"Microsoft.NET.Sdk.Web\">\n\n  <PropertyGroup>\n    <TargetFramework>net9.0</TargetFramework>\n    <!-- Run on a newer major runtime when .NET 9 is absent (e.g. a .NET 10-only machine). -->\n    <RollForward>Major</RollForward>\n    <Nullable>enable</Nullable>\n    <ImplicitUsings>enable</ImplicitUsings>\n    <EnableDefaultCompileItems>false</EnableDefaultCompileItems>\n    <!-- MAAI001: Microsoft.Agents.AI eval-only APIs (HarnessAgentOptions, etc.).\n         MEAI001: Microsoft.Extensions.AI eval-only APIs (AgentRunOptions.ContinuationToken). -->\n    <NoWarn>$(NoWarn);MAAI001;MEAI001</NoWarn>\n  </PropertyGroup>\n\n  <ItemGroup>\n    <!-- Self-defined. -->\n    <Compile Include=\"Program.cs\" />\n    <Compile Include=\"ResearchAgent.cs\" />\n    <!-- Showcase, unchanged. -->\n    <Compile Include=\"SubagentsAgent.cs\" />\n    <Compile Include=\"shared\\LunaChatClientExtensions.cs\" />\n  </ItemGroup>\n\n  <ItemGroup>\n    <PackageReference Include=\"Microsoft.Agents.AI.Harness\" Version=\"1.6.1-preview.260514.1\" />\n    <PackageReference Include=\"Microsoft.Agents.AI.Hosting.AGUI.AspNetCore\" Version=\"1.6.1-preview.260514.1\" />\n    <PackageReference Include=\"Microsoft.Extensions.AI.OpenAI\" Version=\"10.5.1\" />\n    <PackageReference Include=\"OpenAI\" Version=\"2.10.0\" />\n  </ItemGroup>\n\n  <ItemGroup>\n    <None Update=\".env\" CopyToOutputDirectory=\"PreserveNewest\" Condition=\"Exists('.env')\" />\n  </ItemGroup>\n\n</Project>\n",
  "../backend/.env.example": "# Read by Program.cs at startup (variables already set in the environment win).\n# Both the default agent and the sub-agents supervisor read the same two keys.\n\nOPENAI_API_KEY=your_openai_api_key_here\n# Optional. Leave unset for OpenAI's default endpoint.\n# OPENAI_BASE_URL=https://api.openai.com/v1\nOPENAI_CHAT_MODEL_ID=gpt-5.4-mini\n\n# Note: the sub-agents supervisor (SubagentsAgent.cs, from the showcase) does\n# not read OPENAI_CHAT_MODEL_ID. It hard-codes the model \"gpt-6-luna\".\n\n# PORT=8251\n",
};

export function readSource(path: string): string {
  return SOURCES[path] ?? `// Source not generated for ${path}. Run: npm run gen:sources`;
}
